const packages=[{"manifest":{"packageFormatVersion":2,"sdkApiMajor":2,"id":"quizforge.types.multiple-choice","name":"多选题","version":"2.1.2","types":[{"id":"MULTIPLE_CHOICE","label":"多选题","dataVersion":1,"family":"OBJECTIVE","capabilities":["editor","practice","preview","history"],"questionSchema":"question.schema.json","answerSchema":"answer.schema.json","rules":"type.js","editor":"editor.html","renderer":"practice.html","defaultQuestion":"default.json","editorScript":"editor.js","rendererScript":"practice.js","styles":["style.css"],"permissions":["question.edit","bank.save","bank.add","bank.duplicate","bank.delete","answer.write","practice.submit","practice.retry","navigation","sources.open","sources.manage","learning.mode","whiteboard.tools","whiteboard.history","whiteboard.clear","whiteboard.appearance","whiteboard.zoom"]}],"minSdkApiMinor":1},"assets":[{"typeId":"MULTIPLE_CHOICE","defaultQuestion":{"id":"q_template","type":"MULTIPLE_CHOICE","stimulusRefs":[],"prompt":{"kind":"TEXT","text":"选择所有正确选项。"},"payload":{"kind":"CHOICE","options":[{"id":"opt_template_a","content":{"kind":"TEXT","text":"选项 A"}},{"id":"opt_template_b","content":{"kind":"TEXT","text":"选项 B"}},{"id":"opt_template_c","content":{"kind":"TEXT","text":"选项 C"}},{"id":"opt_template_d","content":{"kind":"TEXT","text":"选项 D"}}]},"answerSpec":{"kind":"CHOICE","correctOptionIds":["opt_template_a","opt_template_c"]},"scoreSpec":{"defaultMaxScore":2},"evaluationSpec":null,"analysis":{"kind":"TEXT","text":"在此填写答案与解析。"},"sourceRefs":[]},"questionSchemaSource":"{\r\n  \"type\": \"object\",\r\n  \"required\": [\r\n    \"id\",\r\n    \"type\",\r\n    \"prompt\",\r\n    \"payload\",\r\n    \"answerSpec\",\r\n    \"scoreSpec\"\r\n  ],\r\n  \"properties\": {\r\n    \"type\": {\r\n      \"const\": \"MULTIPLE_CHOICE\"\r\n    },\r\n    \"payload\": {\r\n      \"type\": \"object\"\r\n    },\r\n    \"answerSpec\": {\r\n      \"type\": \"object\"\r\n    }\r\n  }\r\n}\r\n","answerSchemaSource":"{\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"properties\": {\r\n    \"selectedOptionIds\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"type\": \"string\"\r\n      },\r\n      \"uniqueItems\": true\r\n    }\r\n  },\r\n  \"required\": [\r\n    \"selectedOptionIds\"\r\n  ]\r\n}\r\n","editorHtml":"<section class=\"qf-choice-editor\">\n  <header class=\"qf-type-heading qf-editor-heading\">\n    <div class=\"qf-heading-copy\"><span class=\"qf-eyebrow\">题目编辑</span><strong data-type-title>选择题</strong></div>\n    <span data-bank-position class=\"muted\"></span><button type=\"button\" data-bank-save class=\"primary\" hidden>保存题库</button>\n  </header>\n  <nav data-bank-actions class=\"qf-type-actions qf-editor-actions\" aria-label=\"题目操作\" hidden>\n    <select data-bank-add aria-label=\"新增题目类型\"></select>\n    <button type=\"button\" data-bank-duplicate>复制题目</button><button type=\"button\" data-bank-delete class=\"quiet-danger\">删除题目</button>\n  </nav>\n  <section data-delete-confirm class=\"qf-inline-confirm\" hidden>\n    <span>删除当前整张题卡？</span><button type=\"button\" data-delete-cancel>取消</button><button type=\"button\" data-delete-accept class=\"danger\">确认删除</button>\n  </section>\n  <section class=\"qf-editor-section\">\n    <label class=\"qf-field\"><span class=\"qf-field-title\">题干</span><textarea data-prompt rows=\"4\" placeholder=\"输入题目内容…\"></textarea></label>\n  </section>\n  <section class=\"qf-editor-section\">\n    <div class=\"qf-section-heading\"><strong>选项与正确答案</strong><button type=\"button\" data-add-option>＋ 新增选项</button></div>\n    <p data-options-hint class=\"muted\">选择正确答案。</p><div data-options class=\"qf-edit-options\"></div>\n  </section>\n  <section class=\"qf-editor-section qf-score-section\">\n    <label class=\"qf-field\"><span class=\"qf-field-title\">分值</span><span class=\"qf-score-input\"><input data-score type=\"number\" min=\"0.01\" step=\"0.5\"><span>分</span></span></label>\n  </section>\n  <section class=\"qf-editor-section\">\n    <div class=\"qf-section-heading\"><strong>答案与解析</strong><span class=\"muted\">支持富文本</span></div>\n    <div data-analysis class=\"qf-analysis-editor\"></div>\n  </section>\n  <section data-source-section class=\"qf-type-sources\" hidden>\n    <strong>引用来源</strong><div data-sources></div>\n    <div class=\"qf-source-input\"><input data-source-link placeholder=\"粘贴来源链接…\" aria-label=\"来源链接\"><button type=\"button\" data-source-add>添加来源</button></div>\n  </section>\n  <p data-qf-error class=\"practice-error\" role=\"alert\" hidden></p>\n</section>\r\n","rendererHtml":"<section class=\"qf-choice-practice\">\n  <div class=\"qf-type-heading\"><span data-type-label class=\"qf-type-tag\"></span><span data-question-position class=\"muted\"></span></div>\n  <div class=\"qf-type-meta\"><span data-max-score></span><span data-answer-state></span></div>\n  <div data-prompt class=\"qf-choice-prompt\"></div>\n  <p data-choice-hint class=\"qf-choice-hint muted\"></p>\n  <div data-options class=\"qf-choice-options\"></div>\n  <div class=\"qf-type-actions\" data-answer-actions>\n    <button type=\"button\" data-submit-answer class=\"primary\" hidden>提交答案</button><button type=\"button\" data-retry-answer hidden>↻ 重新作答</button>\n  </div>\n  <section data-answer-confirm class=\"qf-inline-confirm\" hidden>\n    <span>确认提交这道题的答案吗？</span><button type=\"button\" data-cancel-answer>继续作答</button><button type=\"button\" data-confirm-answer class=\"primary\">确认提交</button>\n  </section>\n  <section data-result class=\"qf-result-panel\" hidden>\n    <div class=\"qf-result-heading\"><p data-verdict></p><p data-score class=\"qf-result-score\"></p></div>\n    <p data-correct-answer class=\"qf-correct-answer\"></p>\n    <div class=\"qf-result-analysis\"><strong>答案与解析</strong><div data-analysis></div></div>\n  </section>\n  <section data-source-section class=\"qf-type-sources\" hidden><strong>引用来源</strong><div data-sources></div></section>\n  <p data-stage-note class=\"muted\"></p><p data-qf-error class=\"practice-error\" role=\"alert\" hidden></p>\n</section>\r\n","editorSource":"const multiple = true;\r\nconst $ = QF.dom.$, on = QF.dom.on;\r\nconst reply = await QF.editor.getData();\r\nif (!reply.ok) throw new Error(reply.error.message);\r\nlet question = reply.data;\r\nQF.layout.configure({cardWidth:720,maxCardWidth:'100%',horizontalAlign:'center',verticalAlign:'top',padding:20});\r\nQF.ui.configure({ title: false, save: false, position: false, typeLabel: false, add: false, duplicate: false, delete: false, sources: false });\r\n$('[data-type-title]').textContent = multiple ? '多选题编辑' : '单选题编辑';\r\n$('[data-options-hint]').textContent = multiple ? '勾选所有正确答案；题干与选项使用普通文本。' : '点击圆圈设置正确答案；题干与选项使用普通文本。';\r\nlet actionBusy = false, shellRevision = 0;\r\nlet capabilities = {};\r\nasync function shellState() {\r\n  const revision = ++shellRevision;\r\n  const [response, context] = await Promise.all([QF.bank.getState(), QF.host.getContext()]);\r\n  if (revision !== shellRevision) return;\r\n  capabilities = context.ok ? context.data.capabilities : {};\r\n  refreshFields();\r\n  const available = response.ok;\r\n  $('[data-bank-save]').hidden = !available; $('[data-bank-actions]').hidden = !available; $('[data-source-section]').hidden = !available;\r\n  if (!available) return;\r\n  const state = response.data;\r\n  $('[data-bank-position]').textContent = `第 ${state.index + 1} / ${state.count} 题`;\r\n  const select = $('[data-bank-add]'); select.replaceChildren(new Option('＋ 新增题目', ''));\r\n  state.types.forEach(type => select.append(new Option(type.label, type.id)));\r\n  const rows = $('[data-sources]'); rows.replaceChildren();\r\n  state.sources.forEach((source, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-type-source';\r\n    const open = document.createElement('button'); open.type = 'button'; open.textContent = source.label; open.disabled = actionBusy || !capabilities.viewSources || !source.navigable; open.title = source.message; open.dataset.sourceAction = 'open'; open.dataset.sourceIndex = index;\r\n    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message;\r\n    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = '移除'; remove.setAttribute('aria-label', '移除来源 ' + source.label); remove.dataset.sourceAction = 'remove'; remove.dataset.sourceIndex = index; remove.disabled = actionBusy || !capabilities.manageSources;\r\n    row.append(open, message, remove); rows.append(row);\r\n  });\r\n  const granted = context.ok ? context.data.permissions.granted : [];\r\n  for (const [selector, permission] of [['[data-bank-save]', 'bank.save'], ['[data-bank-add]', 'bank.add'], ['[data-bank-duplicate]', 'bank.duplicate'], ['[data-bank-delete]', 'bank.delete'], ['[data-delete-accept]', 'bank.delete'], ['[data-source-add]', 'sources.manage']])\r\n    $(selector).disabled = actionBusy || !state.editable || !granted.includes(permission);\r\n  $('[data-source-link]').disabled = actionBusy || !capabilities.manageSources;\r\n}\r\nasync function runAction(action) {\r\n  if (actionBusy) return; actionBusy = true;\r\n  try { await shellState(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }\r\n  finally { actionBusy = false; await shellState(); }\r\n}\r\non($('[data-bank-save]'), 'click', () => runAction(() => QF.bank.save()));\r\non($('[data-bank-add]'), 'change', () => { const type = $('[data-bank-add]').value; if (type) return runAction(() => QF.bank.addQuestion(type)); });\r\non($('[data-bank-duplicate]'), 'click', () => runAction(() => QF.bank.duplicateQuestion()));\r\non($('[data-bank-delete]'), 'click', () => { $('[data-delete-confirm]').hidden = false; });\r\non($('[data-delete-cancel]'), 'click', () => { $('[data-delete-confirm]').hidden = true; });\r\non($('[data-delete-accept]'), 'click', () => runAction(() => QF.bank.deleteQuestion()));\r\nasync function addSource() {\r\n  const link = $('[data-source-link]').value;\r\n  const response = await runAction(() => QF.sources.add(link));\r\n  if (response?.ok) $('[data-source-link]').value = '';\r\n}\r\non($('[data-source-add]'), 'click', addSource);\r\non($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-action]'); if (button && !button.disabled) return runAction(() => button.dataset.sourceAction === 'open' ? QF.sources.open(Number(button.dataset.sourceIndex)) : QF.sources.remove(Number(button.dataset.sourceIndex))); });\r\non($('[data-source-link]'), 'keydown', event => { if (event.key === 'Enter') { event.preventDefault(); return addSource(); } });\r\n\r\n// Apply a local patch immediately so the next keystroke never builds on an old reply.\r\nlet editRevision = 0;\r\nasync function update(patch) {\r\n  const revision = ++editRevision;\r\n  question = { ...question, ...patch };\r\n  const response = await QF.editor.update(patch);\r\n  if (response.ok) {\r\n    if (revision === editRevision) question = response.data;\r\n  } else {\r\n    QF.ui.notify(response.error.message);\r\n    const saved = await QF.editor.getData();\r\n    if (revision === editRevision && saved.ok) question = saved.data;\r\n  }\r\n  return response;\r\n}\r\nfunction refreshFields() {\r\n  const disabled = actionBusy || !capabilities.editQuestion;\r\n  for (const input of QF.dom.root.querySelectorAll('textarea, input, [data-add-option]')) {\r\n    if (!input.matches('[data-source-link]')) input.disabled = disabled;\r\n  }\r\n  for (const button of QF.dom.root.querySelectorAll('[data-option-remove]'))\r\n    button.disabled = disabled || question.payload.options.length <= 2;\r\n}\r\nfunction updateScore() {\r\n  const value = $('[data-score]').value;\r\n  const score = Number(value);\r\n  if (!value.trim() || !Number.isFinite(score) || score <= 0) {\r\n    QF.ui.notify('分值必须是大于 0 的数字'); return;\r\n  }\r\n  return update({ scoreSpec: { ...question.scoreSpec, defaultMaxScore: score } });\r\n}\r\n$('[data-prompt]').value = question.prompt.text;\r\non($('[data-prompt]'), 'input', () => update({ prompt: { kind: 'TEXT', text: $('[data-prompt]').value } }));\r\n$('[data-score]').value = question.scoreSpec.defaultMaxScore;\r\non($('[data-score]'), 'input', updateScore);\r\nfunction refreshCorrect() {\r\n  question.payload.options.forEach((option, index) => {\r\n    const row = $('[data-options]').children[index];\r\n    const input = row.querySelector('input');\r\n    input.checked = question.answerSpec.correctOptionIds.includes(option.id);\r\n    row.classList.toggle('is-correct', input.checked);\r\n  });\r\n}\r\nfunction options() {\r\n  const box = $('[data-options]'); box.replaceChildren();\r\n  question.payload.options.forEach((option, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-choice-edit-row';\r\n    const correct = document.createElement('input'); correct.type = multiple ? 'checkbox' : 'radio'; correct.name = 'qf-correct-' + question.id; correct.checked = question.answerSpec.correctOptionIds.includes(option.id); correct.title = '设为正确答案';\r\n    row.classList.toggle('is-correct',correct.checked);\r\n    const letter = document.createElement('span'); letter.className='qf-option-letter';letter.textContent = String.fromCharCode(65 + index) + '.';\r\n    correct.setAttribute('aria-label',letter.textContent+' 正确答案');\r\n    const text = document.createElement('textarea'); text.rows = 1; text.value = option.content.text; text.setAttribute('aria-label', letter.textContent + ' 选项');\r\n    const remove = document.createElement('button'); remove.type = 'button'; remove.dataset.optionRemove = ''; remove.textContent = '删除'; remove.disabled = question.payload.options.length <= 2;\r\n    row.append(correct, letter, text, remove); box.append(row);\r\n    on(text, 'input', () => { const next = question.payload.options.map(o => o.id === option.id ? { ...o, content: { kind: 'TEXT', text: text.value } } : o); return update({ payload: { kind: 'CHOICE', options: next } }); });\r\n    on(correct, 'change', async () => { const ids = new Set(question.answerSpec.correctOptionIds); if (multiple) { correct.checked ? ids.add(option.id) : ids.delete(option.id); } else { ids.clear(); ids.add(option.id); } await update({ answerSpec: { kind: 'CHOICE', correctOptionIds: [...ids] } }); refreshCorrect(); });\r\n    on(remove, 'click', async () => { await update({ payload: { kind: 'CHOICE', options: question.payload.options.filter(o => o.id !== option.id) }, answerSpec: { kind: 'CHOICE', correctOptionIds: question.answerSpec.correctOptionIds.filter(id => id !== option.id) } }); options(); });\r\n  });\r\n  refreshFields();\r\n}\r\noptions();\r\non($('[data-add-option]'), 'click', async () => { await update({ payload: { kind: 'CHOICE', options: [...question.payload.options, { id: QF.ids.create('opt_'), content: { kind: 'TEXT', text: '' } }] } }); options(); });\r\nQF.content.mountEditor($('[data-analysis]'), { value: question.analysis, formatting: true, onChange: analysis => update({ analysis }) });\r\n\r\nQF.host.subscribe(shellState); await shellState();\r\n","rendererSource":"const multiple = true;\r\nconst $ = QF.dom.$, on = QF.dom.on;\r\nconst reply = await QF.practice.getQuestion(); if (!reply.ok) throw new Error(reply.error.message);\r\nconst question = reply.data;\r\nQF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'center', padding: 20 });\r\nQF.ui.configure({ typeLabel: false, position: false, score: false, state: false, submit: false, retry: false, confirmation: false, note: false, sources: false, draftToggle: true, draftToolbar: true, draftZoom: true });\r\nlet confirming = false, actionBusy = false, refreshRevision = 0, answerRevision = 0, answerWrites = 0;\r\n$('[data-type-label]').textContent = multiple ? '多选题' : '单选题';\r\n$('[data-choice-hint]').textContent = multiple ? '请选择所有符合题意的选项' : '请选择一个符合题意的选项';\r\nasync function runAction(action) {\r\n  if (actionBusy) return; actionBusy = true;\r\n  try { await refresh(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }\r\n  finally { actionBusy = false; await refresh(); }\r\n}\r\non($('[data-submit-answer]'), 'click', () => { confirming = true; $('[data-answer-confirm]').hidden = false; refresh().then(() => $('[data-confirm-answer]').focus()); });\r\non($('[data-cancel-answer]'), 'click', () => { confirming = false; refresh(); });\r\non($('[data-confirm-answer]'), 'click', () => { confirming = false; return runAction(() => QF.practice.submit()); });\r\non($('[data-retry-answer]'), 'click', () => runAction(() => QF.practice.retry()));\r\non($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-index]'); if (button && !button.disabled) return runAction(() => QF.sources.open(Number(button.dataset.sourceIndex))); });\r\n$('[data-prompt]').textContent = question.prompt.text;\r\nconst controls = [];\r\nquestion.payload.options.forEach((option, index) => {\r\n  const row = document.createElement('label'); row.className = 'qf-choice-option'; row.dataset.optionId = option.id;\r\n  const input = document.createElement('input'); input.type = multiple ? 'checkbox' : 'radio'; input.name = 'qf-choice-' + question.id; input.value = option.id;\r\n  const letter = document.createElement('span'); letter.className = 'qf-option-letter'; letter.textContent = String.fromCharCode(65 + index) + '.'; letter.setAttribute('aria-hidden', 'true');\r\n  const text = document.createElement('span'); text.className = 'qf-option-text'; text.textContent = option.content.text;\r\n  input.setAttribute('aria-label', String.fromCharCode(65 + index) + '. ' + option.content.text);\r\n  const feedback = document.createElement('span'); feedback.className = 'qf-option-feedback'; feedback.hidden = true;\r\n  row.append(input, letter, text, feedback); $('[data-options]').append(row); controls.push({ option, input, row, feedback });\r\n  on(input, 'change', async () => {\r\n    // Invalidate reads already in flight; never repaint an older answer over a newer click.\r\n    ++answerRevision; ++refreshRevision; ++answerWrites;\r\n    const selectedOptionIds = controls.filter(c => c.input.checked).map(c => c.option.id);\r\n    row.classList.toggle('selected', input.checked);\r\n    try {\r\n      const response = await QF.answer.update({ selectedOptionIds });\r\n      if (!response.ok) QF.ui.notify(response.error.message);\r\n    } finally {\r\n      --answerWrites;\r\n      if (!answerWrites) await refresh();\r\n    }\r\n  });\r\n});\r\nasync function refresh() {\r\n  const revision = ++refreshRevision, answerVersion = answerRevision;\r\n  const [a, c, r, s, n] = await Promise.all([QF.answer.get(), QF.host.getContext(), QF.practice.getResult(), QF.practice.getState(), QF.navigation.getState()]);\r\n  if (revision !== refreshRevision || answerVersion !== answerRevision) return;\r\n  if (!a.ok || !c.ok || !r.ok || !s.ok) return;\r\n  const selected = new Set(a.data.selectedOptionIds || []), result = r.data;\r\n  const capabilities = c.data.capabilities, state = s.data;\r\n  const readOnly = c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW';\r\n  const permissions = c.data.permissions.granted;\r\n  $('[data-question-position]').textContent = Number.isInteger(state.index) ? `第 ${state.index + 1} / ${state.total} 题` : '';\r\n  $('[data-max-score]').textContent = `分值：${state.maxScore ?? '未设置'}`;\r\n  $('[data-answer-state]').textContent = ({ UNANSWERED: '未作答', DRAFT: '已选择', SUBMITTED: '已提交', RETRYING: '重试中', REVISING: '修订中' })[state.state] || '';\r\n  if (!capabilities.submit || result || c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW') confirming = false;\r\n  $('[data-answer-confirm]').hidden = !confirming;\r\n  // Temporary interaction locks disable actions without changing the card's layout.\r\n  $('[data-submit-answer]').hidden = readOnly || !permissions.includes('practice.submit') || Boolean(result);\r\n  $('[data-submit-answer]').disabled = actionBusy || confirming || !capabilities.submit || selected.size === 0;\r\n  $('[data-retry-answer]').hidden = readOnly || !permissions.includes('practice.retry') || !result;\r\n  $('[data-retry-answer]').disabled = actionBusy || !capabilities.retry;\r\n  $('[data-confirm-answer]').disabled = actionBusy || !capabilities.submit || selected.size === 0;\r\n  const sourceRows = $('[data-sources]'); sourceRows.replaceChildren();\r\n  const sources = n.ok ? n.data.sources : []; $('[data-source-section]').hidden = !sources.length;\r\n  sources.forEach((source, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-type-source'; const button = document.createElement('button'); button.type = 'button'; button.textContent = source.label; button.disabled = actionBusy || !capabilities.viewSources || !source.navigable; button.dataset.sourceIndex = index;\r\n    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message; row.append(button, message); sourceRows.append(row);\r\n  });\r\n  $('[data-stage-note]').textContent = c.data.mode === 'HISTORY' ? '历史草稿 · 只读' : c.data.mode === 'PREVIEW' ? '只读预览' : '草稿自动保存；提交后冻结，重试从空白草稿开始。';\r\n  const correct = result?.reference?.answerSpec?.correctOptionIds || result?.correctOptionIds || [];\r\n  for (const { option, input, row, feedback } of controls) {\r\n    if (!answerWrites) input.checked = selected.has(option.id);\r\n    input.disabled = actionBusy || confirming || !capabilities.editAnswer;\r\n    row.classList.toggle('selected', input.checked);\r\n    row.classList.toggle('correct', Boolean(result) && correct.includes(option.id));\r\n    row.classList.toggle('incorrect', Boolean(result) && input.checked && !correct.includes(option.id));\r\n    feedback.hidden = !result || (!input.checked && !correct.includes(option.id));\r\n    feedback.textContent = correct.includes(option.id) ? (input.checked ? '正确 · 已选' : '正确答案') : '你的答案';\r\n  }\r\n  $('[data-result]').hidden = !result;\r\n  if (result) {\r\n    $('[data-verdict]').textContent = result.status === 'CORRECT' ? '回答正确' : result.status === 'INCORRECT' ? '回答错误' : '未评分';\r\n    $('[data-verdict]').className = result.status === 'CORRECT' ? 'correct' : 'incorrect';\r\n    $('[data-score]').textContent = '得分：' + (result.score ?? '未评分') + ' / ' + result.maxScore;\r\n    $('[data-correct-answer]').textContent = '正确答案：' + question.payload.options.map((o, i) => correct.includes(o.id) ? String.fromCharCode(65 + i) : null).filter(Boolean).join('、');\r\n    QF.content.render($('[data-analysis]'), result.reference?.analysis || result.analysis || { kind: 'TEXT', text: '' });\r\n  }\r\n}\r\nQF.host.subscribe(refresh); await refresh();\r\n","rulesSource":"QF.defineQuestionType({\r\n  type: \"MULTIPLE_CHOICE\",\r\n  validate(q) {\r\n    const errors=[];\r\n    if(q.prompt?.kind!=='TEXT'||!(q.prompt.text||'').trim()) errors.push('请填写普通文本题干');\r\n    const options=q.payload?.options||[],ids=new Set(options.map(o=>o.id));\r\n    if(options.length<2||ids.size!==options.length) errors.push('至少需要两个具有独立标识的选项');\r\n    if(options.some(o=>o.content?.kind!=='TEXT'||!(o.content.text||'').trim())) errors.push('请填写普通文本选项');\r\n    const correct=q.answerSpec?.correctOptionIds||[];\r\n    if(!correct.length||new Set(correct).size!==correct.length||correct.some(id=>!ids.has(id))) errors.push('请选择有效的正确答案');\r\n    if(!Number.isFinite(q.scoreSpec?.defaultMaxScore)||q.scoreSpec.defaultMaxScore<=0) errors.push('分值必须为正数');\r\n    return errors;\r\n  },\r\n  validateAnswer(q,a) {\r\n    const ids=a.selectedOptionIds||[],available=new Set(q.payload.options.map(o=>o.id));\r\n    if(!Array.isArray(ids)) return {empty:false,errors:['所选答案无效']};\r\n    return {empty:ids.length===0,errors:!Array.isArray(ids)||new Set(ids).size!==ids.length||ids.some(id=>!available.has(id))?['所选答案无效']:[]};\r\n  },\r\n  grade(ctx) {\r\n    const selected=new Set(ctx.answer.selectedOptionIds||[]),correct=ctx.question.answerSpec.correctOptionIds;\r\n    const same=selected.size===correct.length&&correct.every(id=>selected.has(id));\r\n    return ctx.reportResult({score:same?ctx.maxScore:0});\r\n  }\r\n});\r\n\r\n","stylesSource":".qf-choice-editor,.qf-choice-practice {\n  --choice-accent:#7962ad;--choice-soft:#f5f1fb;--choice-line:#e8e3ed;--choice-muted:#8a8295;\n  font:15px/1.65 Arial,\"Microsoft YaHei\",sans-serif;color:#302c3b;min-width:0;\n}\n.qf-choice-editor *, .qf-choice-practice *{box-sizing:border-box}\n.qf-extension-page [hidden]{display:none!important}\n.qf-choice-editor .muted,.qf-choice-practice .muted{font-size:12px;color:var(--choice-muted);margin:0}\n.qf-type-heading{display:flex;align-items:center;justify-content:space-between;gap:14px}\n.qf-heading-copy{display:grid;gap:3px;flex:1}\n.qf-eyebrow{font-size:11px;color:var(--choice-muted);letter-spacing:1px}\n.qf-editor-heading strong{font-size:22px;font-weight:600;line-height:1.45}\n.qf-type-tag{padding:4px 11px;border-radius:6px;color:var(--choice-accent);background:#eee9f7;font-size:12px}\n.qf-type-meta{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:var(--choice-muted);margin:12px 0 24px}\n.qf-type-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:24px 0 0}\n.qf-editor-actions{margin:18px 0 6px;padding-bottom:20px;border-bottom:1px solid var(--choice-line)}\n.qf-choice-editor button,.qf-choice-practice button,.qf-choice-editor select {\n  font:13px/1.5 Arial,\"Microsoft YaHei\",sans-serif;min-height:36px;padding:7px 13px;\n  border:1px solid #ded7e9;border-radius:8px;background:white;color:var(--choice-accent);cursor:pointer;\n  transition:background .15s,border-color .15s;\n}\n.qf-choice-editor button:hover,.qf-choice-practice button:hover{background:var(--choice-soft);border-color:#c9bcde}\n.qf-choice-editor button.primary,.qf-choice-practice button.primary{background:var(--choice-accent);color:white;border-color:var(--choice-accent);padding-left:20px;padding-right:20px}\n.qf-choice-editor button.primary:hover,.qf-choice-practice button.primary:hover{background:#6a539d}\n.qf-choice-editor button:disabled,.qf-choice-practice button:disabled{opacity:.45;cursor:default}\n.qf-choice-editor button.danger,.qf-choice-editor button.quiet-danger{color:#bd5264}\n.qf-choice-editor button:focus-visible,.qf-choice-practice button:focus-visible,.qf-choice-editor select:focus-visible{outline:2px solid #ad97d5;outline-offset:3px}\n.qf-editor-section{margin-top:24px}\n.qf-field{display:grid;gap:10px}\n.qf-field-title,.qf-section-heading strong,.qf-type-sources>strong{font-size:14px;font-weight:600}\n.qf-section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}\n.qf-choice-editor textarea,.qf-choice-editor input[type=number],.qf-source-input input {\n  width:100%;font:inherit;line-height:1.65;padding:11px 13px;border:1px solid #dfd9e8;border-radius:8px;\n  background:#fff;color:inherit;outline:none;\n}\n.qf-choice-editor textarea{resize:vertical;display:block}\n.qf-choice-editor textarea:focus,.qf-choice-editor input[type=number]:focus,.qf-source-input input:focus{border-color:#a18ac6;box-shadow:0 0 0 3px #7962ad0d}\n.qf-edit-options{display:grid;gap:10px;margin-top:14px}\n.qf-choice-edit-row{display:grid;grid-template-columns:20px 28px minmax(0,1fr) auto;align-items:center;gap:10px;padding:9px 10px;border:1px solid var(--choice-line);border-radius:10px;background:#fcfbfd}\n.qf-choice-edit-row.is-correct{background:var(--choice-soft);border-color:#d8cbe9}\n.qf-option-letter{font-weight:600;color:#756b86;font-size:14px;flex:none}\n.qf-choice-edit-row.is-correct .qf-option-letter{color:var(--choice-accent)}\n.qf-choice-edit-row textarea{padding:8px 10px;min-height:42px;font-size:14px}\n.qf-choice-edit-row button{padding:6px 8px;min-height:32px;border-color:transparent;background:transparent;color:var(--choice-muted);font-size:12px}\n.qf-choice-edit-row button:hover{color:#bd5264;background:#fff1f3;border-color:transparent}\n.qf-score-input{display:flex;align-items:center;gap:10px;color:var(--choice-muted);font-size:13px}\n.qf-score-input input[type=number]{width:112px;color:#302c3b}\n.qf-analysis-editor{margin-top:12px}\n.qf-choice-prompt{margin:0 0 14px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:18px;font-weight:500;line-height:1.8}\n.qf-choice-hint{margin-bottom:14px!important}\n.qf-choice-options{display:grid;gap:10px}\n.qf-choice-option{display:flex;align-items:flex-start;gap:12px;padding:14px 15px;border:1px solid #eeeaf2;border-radius:10px;background:#fcfbfd;cursor:pointer;transition:background .15s,border-color .15s}\n.qf-choice-option:hover{background:#f8f5fc;border-color:#d8cde7}\n.qf-choice-option.selected{background:var(--choice-soft);border-color:#d4c5e7}\n.qf-choice-option .qf-option-text{flex:1;min-width:0;white-space:pre-wrap;overflow-wrap:anywhere}\n.qf-choice-option input,.qf-choice-edit-row>input {\n  appearance:none;-webkit-appearance:none;width:20px;height:20px;flex:none;position:relative;\n  border:1.5px solid #cec7d6;border-radius:50%;margin:2px 0 0;background:white;cursor:pointer;\n}\n.qf-choice-option input[type=checkbox],.qf-choice-edit-row>input[type=checkbox]{border-radius:5px}\n.qf-choice-option input:checked,.qf-choice-edit-row>input:checked{border-color:var(--choice-accent)}\n.qf-choice-option input:checked:after,.qf-choice-edit-row>input:checked:after{content:\"\";position:absolute;inset:4px;background:var(--choice-accent);border-radius:50%}\n.qf-choice-option input[type=checkbox]:checked:after,.qf-choice-edit-row>input[type=checkbox]:checked:after{content:\"✓\";inset:-4px 0 0;color:var(--choice-accent);background:transparent;font-size:19px;text-align:center}\n.qf-choice-option input:focus-visible,.qf-choice-edit-row>input:focus-visible{outline:2px solid #ad97d5;outline-offset:3px}\n.qf-choice-option input:disabled{opacity:1;cursor:default}\n.qf-choice-option.correct{background:#edf7f3;border-color:#cce8dd;color:#13876d}\n.qf-choice-option.incorrect{background:#fff0f2;border-color:#f2d3db;color:#c64b63}\n.qf-choice-option.correct .qf-option-letter{color:#13876d}\n.qf-choice-option.incorrect .qf-option-letter{color:#c64b63}\n.qf-option-feedback{font-size:11px;line-height:24px;flex:none;white-space:nowrap}\n.qf-inline-confirm{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:14px 16px;margin-top:16px;background:var(--choice-soft);border:1px solid #e0d6ed;border-radius:10px;font-size:13px}\n.qf-inline-confirm>span{flex:1;min-width:180px}\n.qf-result-panel{margin-top:26px;padding:20px;border:1px solid var(--choice-line);border-radius:12px;background:#fcfbfd}\n.qf-result-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}\n.qf-result-heading p{margin:0}\n.qf-result-heading [data-verdict]{font-size:15px;font-weight:600}\n.qf-result-heading .correct{color:#13876d}\n.qf-result-heading .incorrect{color:#c64b63}\n.qf-result-score{font-size:13px;color:var(--choice-accent);padding:4px 10px;background:#eee9f7;border-radius:6px}\n.qf-correct-answer{margin:12px 0 0;font-size:13px;color:#6a6178}\n.qf-result-analysis{border-top:1px solid var(--choice-line);padding-top:16px;margin-top:16px}\n.qf-result-analysis>strong{font-size:13px;font-weight:600}\n.qf-result-analysis [data-analysis]{margin-top:8px;overflow-wrap:anywhere}\n.qf-type-sources{border-top:1px solid var(--choice-line);padding-top:18px;margin-top:26px;font-size:13px}\n.qf-type-source{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-top:10px}\n.qf-type-source>button:first-child{max-width:100%;overflow-wrap:anywhere;text-align:left}\n.qf-type-source>.muted{flex:1}\n.qf-source-input{display:flex;align-items:center;gap:10px;margin-top:12px}\n.qf-source-input input{flex:1;min-width:0;font-size:13px}\n.qf-source-input button{flex:none}\n.qf-choice-practice [data-stage-note]{margin-top:24px;font-size:11px;line-height:1.7}\n@media(max-width:520px){\n  .qf-editor-heading{flex-wrap:wrap}.qf-heading-copy{min-width:130px}.qf-editor-heading strong{font-size:20px}\n  .qf-choice-edit-row{grid-template-columns:20px 22px minmax(0,1fr) auto;gap:6px;padding:8px}\n  .qf-choice-edit-row button{padding:6px 3px}.qf-choice-option{padding:12px 10px;gap:8px}\n  .qf-option-feedback{font-size:10px}.qf-result-panel{padding:16px}.qf-choice-prompt{font-size:17px}\n}\r\n"}]},{"manifest":{"packageFormatVersion":2,"sdkApiMajor":2,"id":"quizforge.types.single-choice","name":"单选题","version":"2.1.2","types":[{"id":"SINGLE_CHOICE","label":"单选题","dataVersion":1,"family":"OBJECTIVE","capabilities":["editor","practice","preview","history"],"questionSchema":"question.schema.json","answerSchema":"answer.schema.json","rules":"type.js","editor":"editor.html","renderer":"practice.html","defaultQuestion":"default.json","editorScript":"editor.js","rendererScript":"practice.js","styles":["style.css"],"permissions":["question.edit","bank.save","bank.add","bank.duplicate","bank.delete","answer.write","practice.submit","practice.retry","navigation","sources.open","sources.manage","learning.mode","whiteboard.tools","whiteboard.history","whiteboard.clear","whiteboard.appearance","whiteboard.zoom"]}],"minSdkApiMinor":1},"assets":[{"typeId":"SINGLE_CHOICE","defaultQuestion":{"id":"q_template","type":"SINGLE_CHOICE","stimulusRefs":[],"prompt":{"kind":"TEXT","text":"请选择一个正确选项。"},"payload":{"kind":"CHOICE","options":[{"id":"opt_template_a","content":{"kind":"TEXT","text":"选项 A"}},{"id":"opt_template_b","content":{"kind":"TEXT","text":"选项 B"}},{"id":"opt_template_c","content":{"kind":"TEXT","text":"选项 C"}},{"id":"opt_template_d","content":{"kind":"TEXT","text":"选项 D"}}]},"answerSpec":{"kind":"CHOICE","correctOptionIds":["opt_template_a"]},"scoreSpec":{"defaultMaxScore":1},"evaluationSpec":null,"analysis":{"kind":"TEXT","text":"在此填写答案与解析。"},"sourceRefs":[]},"questionSchemaSource":"{\r\n  \"type\": \"object\",\r\n  \"required\": [\r\n    \"id\",\r\n    \"type\",\r\n    \"prompt\",\r\n    \"payload\",\r\n    \"answerSpec\",\r\n    \"scoreSpec\"\r\n  ],\r\n  \"properties\": {\r\n    \"type\": {\r\n      \"const\": \"SINGLE_CHOICE\"\r\n    },\r\n    \"payload\": {\r\n      \"type\": \"object\"\r\n    },\r\n    \"answerSpec\": {\r\n      \"type\": \"object\"\r\n    }\r\n  }\r\n}\r\n","answerSchemaSource":"{\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"properties\": {\r\n    \"selectedOptionIds\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"type\": \"string\"\r\n      },\r\n      \"uniqueItems\": true\r\n    }\r\n  },\r\n  \"required\": [\r\n    \"selectedOptionIds\"\r\n  ]\r\n}\r\n","editorHtml":"<section class=\"qf-choice-editor\">\n  <header class=\"qf-type-heading qf-editor-heading\">\n    <div class=\"qf-heading-copy\"><span class=\"qf-eyebrow\">题目编辑</span><strong data-type-title>选择题</strong></div>\n    <span data-bank-position class=\"muted\"></span><button type=\"button\" data-bank-save class=\"primary\" hidden>保存题库</button>\n  </header>\n  <nav data-bank-actions class=\"qf-type-actions qf-editor-actions\" aria-label=\"题目操作\" hidden>\n    <select data-bank-add aria-label=\"新增题目类型\"></select>\n    <button type=\"button\" data-bank-duplicate>复制题目</button><button type=\"button\" data-bank-delete class=\"quiet-danger\">删除题目</button>\n  </nav>\n  <section data-delete-confirm class=\"qf-inline-confirm\" hidden>\n    <span>删除当前整张题卡？</span><button type=\"button\" data-delete-cancel>取消</button><button type=\"button\" data-delete-accept class=\"danger\">确认删除</button>\n  </section>\n  <section class=\"qf-editor-section\">\n    <label class=\"qf-field\"><span class=\"qf-field-title\">题干</span><textarea data-prompt rows=\"4\" placeholder=\"输入题目内容…\"></textarea></label>\n  </section>\n  <section class=\"qf-editor-section\">\n    <div class=\"qf-section-heading\"><strong>选项与正确答案</strong><button type=\"button\" data-add-option>＋ 新增选项</button></div>\n    <p data-options-hint class=\"muted\">选择正确答案。</p><div data-options class=\"qf-edit-options\"></div>\n  </section>\n  <section class=\"qf-editor-section qf-score-section\">\n    <label class=\"qf-field\"><span class=\"qf-field-title\">分值</span><span class=\"qf-score-input\"><input data-score type=\"number\" min=\"0.01\" step=\"0.5\"><span>分</span></span></label>\n  </section>\n  <section class=\"qf-editor-section\">\n    <div class=\"qf-section-heading\"><strong>答案与解析</strong><span class=\"muted\">支持富文本</span></div>\n    <div data-analysis class=\"qf-analysis-editor\"></div>\n  </section>\n  <section data-source-section class=\"qf-type-sources\" hidden>\n    <strong>引用来源</strong><div data-sources></div>\n    <div class=\"qf-source-input\"><input data-source-link placeholder=\"粘贴来源链接…\" aria-label=\"来源链接\"><button type=\"button\" data-source-add>添加来源</button></div>\n  </section>\n  <p data-qf-error class=\"practice-error\" role=\"alert\" hidden></p>\n</section>\r\n","rendererHtml":"<section class=\"qf-choice-practice\">\n  <div class=\"qf-type-heading\"><span data-type-label class=\"qf-type-tag\"></span><span data-question-position\n      class=\"muted\"></span></div>\n  <div class=\"qf-type-meta\"><span data-max-score></span><span data-answer-state></span></div>\n  <div data-prompt class=\"qf-choice-prompt\"></div>\n  <p data-choice-hint class=\"qf-choice-hint muted\"></p>\n  <div data-options class=\"qf-choice-options\"></div>\n  <div class=\"qf-type-actions\" data-answer-actions>\n    <button type=\"button\" data-submit-answer class=\"primary\" hidden>提交答案</button><button type=\"button\" data-retry-answer\n      hidden>↻ 重新作答</button>\n  </div>\n  <section data-answer-confirm class=\"qf-inline-confirm\" hidden>\n    <span>确认提交这道题的答案吗？</span><button type=\"button\" data-cancel-answer>继续作答</button><button type=\"button\"\n      data-confirm-answer class=\"primary\">确认提交</button>\n  </section>\n  <section data-result class=\"qf-result-panel\" hidden>\n    <div class=\"qf-result-heading\">\n      <p data-verdict></p>\n      <p data-score class=\"qf-result-score\"></p>\n    </div>\n    <p data-correct-answer class=\"qf-correct-answer\"></p>\n    <div class=\"qf-result-analysis\"><strong>答案与解析</strong>\n      <div data-analysis></div>\n    </div>\n  </section>\n  <section data-source-section class=\"qf-type-sources\" hidden><strong>引用来源</strong>\n    <div data-sources></div>\n  </section>\n  <p data-stage-note class=\"muted\"></p>\n  <p data-qf-error class=\"practice-error\" role=\"alert\" hidden></p>\n</section>","editorSource":"const multiple = false;\r\nconst $ = QF.dom.$, on = QF.dom.on;\r\nconst reply = await QF.editor.getData();\r\nif (!reply.ok) throw new Error(reply.error.message);\r\nlet question = reply.data;\r\nQF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'top', padding: 20 });\r\nQF.ui.configure({ title: false, save: false, position: false, typeLabel: false, add: false, duplicate: false, delete: false, sources: false });\r\n$('[data-type-title]').textContent = multiple ? '多选题编辑' : '单选题编辑';\r\n$('[data-options-hint]').textContent = multiple ? '勾选所有正确答案；题干与选项使用普通文本。' : '点击圆圈设置正确答案；题干与选项使用普通文本。';\r\nlet actionBusy = false, shellRevision = 0;\r\nlet capabilities = {};\r\nasync function shellState() {\r\n  const revision = ++shellRevision;\r\n  const [response, context] = await Promise.all([QF.bank.getState(), QF.host.getContext()]);\r\n  if (revision !== shellRevision) return;\r\n  capabilities = context.ok ? context.data.capabilities : {};\r\n  refreshFields();\r\n  const available = response.ok;\r\n  $('[data-bank-save]').hidden = !available; $('[data-bank-actions]').hidden = !available; $('[data-source-section]').hidden = !available;\r\n  if (!available) return;\r\n  const state = response.data;\r\n  $('[data-bank-position]').textContent = `第 ${state.index + 1} / ${state.count} 题`;\r\n  const select = $('[data-bank-add]'); select.replaceChildren(new Option('＋ 新增题目', ''));\r\n  state.types.forEach(type => select.append(new Option(type.label, type.id)));\r\n  const rows = $('[data-sources]'); rows.replaceChildren();\r\n  state.sources.forEach((source, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-type-source';\r\n    const open = document.createElement('button'); open.type = 'button'; open.textContent = source.label; open.disabled = actionBusy || !capabilities.viewSources || !source.navigable; open.title = source.message; open.dataset.sourceAction = 'open'; open.dataset.sourceIndex = index;\r\n    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message;\r\n    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = '移除'; remove.setAttribute('aria-label', '移除来源 ' + source.label); remove.dataset.sourceAction = 'remove'; remove.dataset.sourceIndex = index; remove.disabled = actionBusy || !capabilities.manageSources;\r\n    row.append(open, message, remove); rows.append(row);\r\n  });\r\n  const granted = context.ok ? context.data.permissions.granted : [];\r\n  for (const [selector, permission] of [['[data-bank-save]', 'bank.save'], ['[data-bank-add]', 'bank.add'], ['[data-bank-duplicate]', 'bank.duplicate'], ['[data-bank-delete]', 'bank.delete'], ['[data-delete-accept]', 'bank.delete'], ['[data-source-add]', 'sources.manage']])\r\n    $(selector).disabled = actionBusy || !state.editable || !granted.includes(permission);\r\n  $('[data-source-link]').disabled = actionBusy || !capabilities.manageSources;\r\n}\r\nasync function runAction(action) {\r\n  if (actionBusy) return; actionBusy = true;\r\n  try { await shellState(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }\r\n  finally { actionBusy = false; await shellState(); }\r\n}\r\non($('[data-bank-save]'), 'click', () => runAction(() => QF.bank.save()));\r\non($('[data-bank-add]'), 'change', () => { const type = $('[data-bank-add]').value; if (type) return runAction(() => QF.bank.addQuestion(type)); });\r\non($('[data-bank-duplicate]'), 'click', () => runAction(() => QF.bank.duplicateQuestion()));\r\non($('[data-bank-delete]'), 'click', () => { $('[data-delete-confirm]').hidden = false; });\r\non($('[data-delete-cancel]'), 'click', () => { $('[data-delete-confirm]').hidden = true; });\r\non($('[data-delete-accept]'), 'click', () => runAction(() => QF.bank.deleteQuestion()));\r\nasync function addSource() {\r\n  const link = $('[data-source-link]').value;\r\n  const response = await runAction(() => QF.sources.add(link));\r\n  if (response?.ok) $('[data-source-link]').value = '';\r\n}\r\non($('[data-source-add]'), 'click', addSource);\r\non($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-action]'); if (button && !button.disabled) return runAction(() => button.dataset.sourceAction === 'open' ? QF.sources.open(Number(button.dataset.sourceIndex)) : QF.sources.remove(Number(button.dataset.sourceIndex))); });\r\non($('[data-source-link]'), 'keydown', event => { if (event.key === 'Enter') { event.preventDefault(); return addSource(); } });\r\n\r\n// Apply a local patch immediately so the next keystroke never builds on an old reply.\r\nlet editRevision = 0;\r\nasync function update(patch) {\r\n  const revision = ++editRevision;\r\n  question = { ...question, ...patch };\r\n  const response = await QF.editor.update(patch);\r\n  if (response.ok) {\r\n    if (revision === editRevision) question = response.data;\r\n  } else {\r\n    QF.ui.notify(response.error.message);\r\n    const saved = await QF.editor.getData();\r\n    if (revision === editRevision && saved.ok) question = saved.data;\r\n  }\r\n  return response;\r\n}\r\nfunction refreshFields() {\r\n  const disabled = actionBusy || !capabilities.editQuestion;\r\n  for (const input of QF.dom.root.querySelectorAll('textarea, input, [data-add-option]')) {\r\n    if (!input.matches('[data-source-link]')) input.disabled = disabled;\r\n  }\r\n  for (const button of QF.dom.root.querySelectorAll('[data-option-remove]'))\r\n    button.disabled = disabled || question.payload.options.length <= 2;\r\n}\r\nfunction updateScore() {\r\n  const value = $('[data-score]').value;\r\n  const score = Number(value);\r\n  if (!value.trim() || !Number.isFinite(score) || score <= 0) {\r\n    QF.ui.notify('分值必须是大于 0 的数字'); return;\r\n  }\r\n  return update({ scoreSpec: { ...question.scoreSpec, defaultMaxScore: score } });\r\n}\r\n$('[data-prompt]').value = question.prompt.text;\r\non($('[data-prompt]'), 'input', () => update({ prompt: { kind: 'TEXT', text: $('[data-prompt]').value } }));\r\n$('[data-score]').value = question.scoreSpec.defaultMaxScore;\r\non($('[data-score]'), 'input', updateScore);\r\nfunction refreshCorrect() {\r\n  question.payload.options.forEach((option, index) => {\r\n    const row = $('[data-options]').children[index];\r\n    const input = row.querySelector('input');\r\n    input.checked = question.answerSpec.correctOptionIds.includes(option.id);\r\n    row.classList.toggle('is-correct', input.checked);\r\n  });\r\n}\r\nfunction options() {\r\n  const box = $('[data-options]'); box.replaceChildren();\r\n  question.payload.options.forEach((option, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-choice-edit-row';\r\n    const correct = document.createElement('input'); correct.type = multiple ? 'checkbox' : 'radio'; correct.name = 'qf-correct-' + question.id; correct.checked = question.answerSpec.correctOptionIds.includes(option.id); correct.title = '设为正确答案';\r\n    row.classList.toggle('is-correct', correct.checked);\r\n    const letter = document.createElement('span'); letter.className = 'qf-option-letter'; letter.textContent = String.fromCharCode(65 + index) + '.';\r\n    correct.setAttribute('aria-label', letter.textContent + ' 正确答案');\r\n    const text = document.createElement('textarea'); text.rows = 1; text.value = option.content.text; text.setAttribute('aria-label', letter.textContent + ' 选项');\r\n    const remove = document.createElement('button'); remove.type = 'button'; remove.dataset.optionRemove = ''; remove.textContent = '删除'; remove.disabled = question.payload.options.length <= 2;\r\n    row.append(correct, letter, text, remove); box.append(row);\r\n    on(text, 'input', () => { const next = question.payload.options.map(o => o.id === option.id ? { ...o, content: { kind: 'TEXT', text: text.value } } : o); return update({ payload: { kind: 'CHOICE', options: next } }); });\r\n    on(correct, 'change', async () => { const ids = new Set(question.answerSpec.correctOptionIds); if (multiple) { correct.checked ? ids.add(option.id) : ids.delete(option.id); } else { ids.clear(); ids.add(option.id); } await update({ answerSpec: { kind: 'CHOICE', correctOptionIds: [...ids] } }); refreshCorrect(); });\r\n    on(remove, 'click', async () => { await update({ payload: { kind: 'CHOICE', options: question.payload.options.filter(o => o.id !== option.id) }, answerSpec: { kind: 'CHOICE', correctOptionIds: question.answerSpec.correctOptionIds.filter(id => id !== option.id) } }); options(); });\r\n  });\r\n  refreshFields();\r\n}\r\noptions();\r\non($('[data-add-option]'), 'click', async () => { await update({ payload: { kind: 'CHOICE', options: [...question.payload.options, { id: QF.ids.create('opt_'), content: { kind: 'TEXT', text: '' } }] } }); options(); });\r\nQF.content.mountEditor($('[data-analysis]'), { value: question.analysis, formatting: true, onChange: analysis => update({ analysis }) });\r\n\r\nQF.host.subscribe(shellState); await shellState();\r\n","rendererSource":"const multiple = false;\r\nconst $ = QF.dom.$, on = QF.dom.on;\r\nconst reply = await QF.practice.getQuestion(); if (!reply.ok) throw new Error(reply.error.message);\r\nconst question = reply.data;\r\nQF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'center', padding: 20 });\r\nQF.ui.configure({ typeLabel: false, position: false, score: false, state: false, submit: false, retry: false, confirmation: false, note: false, sources: false, draftToggle: true, draftToolbar: true, draftZoom: true });\r\nlet confirming = false, actionBusy = false, refreshRevision = 0, answerRevision = 0, answerWrites = 0;\r\n$('[data-type-label]').textContent = multiple ? '多选题' : '单选题';\r\n$('[data-choice-hint]').textContent = multiple ? '请选择所有符合题意的选项' : '请选择一个符合题意的选项';\r\nasync function runAction(action) {\r\n  if (actionBusy) return; actionBusy = true;\r\n  try { await refresh(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }\r\n  finally { actionBusy = false; await refresh(); }\r\n}\r\non($('[data-submit-answer]'), 'click', () => { confirming = true; $('[data-answer-confirm]').hidden = false; refresh().then(() => $('[data-confirm-answer]').focus()); });\r\non($('[data-cancel-answer]'), 'click', () => { confirming = false; refresh(); });\r\non($('[data-confirm-answer]'), 'click', () => { confirming = false; return runAction(() => QF.practice.submit()); });\r\non($('[data-retry-answer]'), 'click', () => runAction(() => QF.practice.retry()));\r\non($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-index]'); if (button && !button.disabled) return runAction(() => QF.sources.open(Number(button.dataset.sourceIndex))); });\r\n$('[data-prompt]').textContent = question.prompt.text;\r\nconst controls = [];\r\nquestion.payload.options.forEach((option, index) => {\r\n  const row = document.createElement('label'); row.className = 'qf-choice-option'; row.dataset.optionId = option.id;\r\n  const input = document.createElement('input'); input.type = multiple ? 'checkbox' : 'radio'; input.name = 'qf-choice-' + question.id; input.value = option.id;\r\n  const letter = document.createElement('span'); letter.className = 'qf-option-letter'; letter.textContent = String.fromCharCode(65 + index) + '.'; letter.setAttribute('aria-hidden', 'true');\r\n  const text = document.createElement('span'); text.className = 'qf-option-text'; text.textContent = option.content.text;\r\n  input.setAttribute('aria-label', String.fromCharCode(65 + index) + '. ' + option.content.text);\r\n  const feedback = document.createElement('span'); feedback.className = 'qf-option-feedback'; feedback.hidden = true;\r\n  row.append(input, letter, text, feedback); $('[data-options]').append(row); controls.push({ option, input, row, feedback });\r\n  on(input, 'change', async () => {\r\n    // Invalidate reads already in flight; never repaint an older answer over a newer click.\r\n    ++answerRevision; ++refreshRevision; ++answerWrites;\r\n    const selectedOptionIds = controls.filter(c => c.input.checked).map(c => c.option.id);\r\n    row.classList.toggle('selected', input.checked);\r\n    try {\r\n      const response = await QF.answer.update({ selectedOptionIds });\r\n      if (!response.ok) QF.ui.notify(response.error.message);\r\n    } finally {\r\n      --answerWrites;\r\n      if (!answerWrites) await refresh();\r\n    }\r\n  });\r\n});\r\nasync function refresh() {\r\n  const revision = ++refreshRevision, answerVersion = answerRevision;\r\n  const [a, c, r, s, n] = await Promise.all([QF.answer.get(), QF.host.getContext(), QF.practice.getResult(), QF.practice.getState(), QF.navigation.getState()]);\r\n  if (revision !== refreshRevision || answerVersion !== answerRevision) return;\r\n  if (!a.ok || !c.ok || !r.ok || !s.ok) return;\r\n  const selected = new Set(a.data.selectedOptionIds || []), result = r.data;\r\n  const capabilities = c.data.capabilities, state = s.data;\r\n  const readOnly = c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW';\r\n  const permissions = c.data.permissions.granted;\r\n  $('[data-question-position]').textContent = Number.isInteger(state.index) ? `第 ${state.index + 1} / ${state.total} 题` : '';\r\n  $('[data-max-score]').textContent = `分值：${state.maxScore ?? '未设置'}`;\r\n  $('[data-answer-state]').textContent = ({ UNANSWERED: '未作答', DRAFT: '已选择', SUBMITTED: '已提交', RETRYING: '重试中', REVISING: '修订中' })[state.state] || '';\r\n  if (!capabilities.submit || result || c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW') confirming = false;\r\n  $('[data-answer-confirm]').hidden = !confirming;\r\n  // Temporary interaction locks disable actions without changing the card's layout.\r\n  $('[data-submit-answer]').hidden = readOnly || !permissions.includes('practice.submit') || Boolean(result);\r\n  $('[data-submit-answer]').disabled = actionBusy || confirming || !capabilities.submit || selected.size === 0;\r\n  $('[data-retry-answer]').hidden = readOnly || !permissions.includes('practice.retry') || !result;\r\n  $('[data-retry-answer]').disabled = actionBusy || !capabilities.retry;\r\n  $('[data-confirm-answer]').disabled = actionBusy || !capabilities.submit || selected.size === 0;\r\n  const sourceRows = $('[data-sources]'); sourceRows.replaceChildren();\r\n  const sources = n.ok ? n.data.sources : []; $('[data-source-section]').hidden = !sources.length;\r\n  sources.forEach((source, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-type-source'; const button = document.createElement('button'); button.type = 'button'; button.textContent = source.label; button.disabled = actionBusy || !capabilities.viewSources || !source.navigable; button.dataset.sourceIndex = index;\r\n    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message; row.append(button, message); sourceRows.append(row);\r\n  });\r\n  $('[data-stage-note]').textContent = c.data.mode === 'HISTORY' ? '历史草稿 · 只读' : c.data.mode === 'PREVIEW' ? '只读预览' : '草稿自动保存；提交后冻结，重试从空白草稿开始。';\r\n  const correct = result?.reference?.answerSpec?.correctOptionIds || result?.correctOptionIds || [];\r\n  for (const { option, input, row, feedback } of controls) {\r\n    if (!answerWrites) input.checked = selected.has(option.id);\r\n    input.disabled = actionBusy || confirming || !capabilities.editAnswer;\r\n    row.classList.toggle('selected', input.checked);\r\n    row.classList.toggle('correct', Boolean(result) && correct.includes(option.id));\r\n    row.classList.toggle('incorrect', Boolean(result) && input.checked && !correct.includes(option.id));\r\n    feedback.hidden = !result || (!input.checked && !correct.includes(option.id));\r\n    feedback.textContent = correct.includes(option.id) ? (input.checked ? '正确 · 已选' : '正确答案') : '你的答案';\r\n  }\r\n  $('[data-result]').hidden = !result;\r\n  if (result) {\r\n    $('[data-verdict]').textContent = result.status === 'CORRECT' ? '回答正确' : result.status === 'INCORRECT' ? '回答错误' : '未评分';\r\n    $('[data-verdict]').className = result.status === 'CORRECT' ? 'correct' : 'incorrect';\r\n    $('[data-score]').textContent = '得分：' + (result.score ?? '未评分') + ' / ' + result.maxScore;\r\n    $('[data-correct-answer]').textContent = '正确答案：' + question.payload.options.map((o, i) => correct.includes(o.id) ? String.fromCharCode(65 + i) : null).filter(Boolean).join('、');\r\n    QF.content.render($('[data-analysis]'), result.reference?.analysis || result.analysis || { kind: 'TEXT', text: '' });\r\n  }\r\n}\r\nQF.host.subscribe(refresh); await refresh();\r\n","rulesSource":"QF.defineQuestionType({\r\n  type: \"SINGLE_CHOICE\",\r\n  validate(q) {\r\n    const errors = [];\r\n    if (q.prompt?.kind !== 'TEXT' || !(q.prompt.text || '').trim()) errors.push('请填写普通文本题干');\r\n    const options = q.payload?.options || [], ids = new Set(options.map(o => o.id));\r\n    if (options.length < 2 || ids.size !== options.length) errors.push('至少需要两个具有独立标识的选项');\r\n    if (options.some(o => o.content?.kind !== 'TEXT' || !(o.content.text || '').trim())) errors.push('请填写普通文本选项');\r\n    const correct = q.answerSpec?.correctOptionIds || [];\r\n    if (!correct.length || new Set(correct).size !== correct.length || correct.some(id => !ids.has(id)) || correct.length !== 1) errors.push('请选择有效的正确答案');\r\n    if (!Number.isFinite(q.scoreSpec?.defaultMaxScore) || q.scoreSpec.defaultMaxScore <= 0) errors.push('分值必须为正数');\r\n    return errors;\r\n  },\r\n  validateAnswer(q, a) {\r\n    const ids = a.selectedOptionIds || [], available = new Set(q.payload.options.map(o => o.id));\r\n    if (!Array.isArray(ids)) return { empty: false, errors: ['所选答案无效'] };\r\n    return { empty: ids.length === 0, errors: !Array.isArray(ids) || new Set(ids).size !== ids.length || ids.some(id => !available.has(id)) || ids.length > 1 ? ['所选答案无效'] : [] };\r\n  },\r\n  grade(ctx) {\r\n    const selected = new Set(ctx.answer.selectedOptionIds || []), correct = ctx.question.answerSpec.correctOptionIds;\r\n    const same = selected.size === correct.length && correct.every(id => selected.has(id));\r\n    return ctx.reportResult({ score: same ? ctx.maxScore : 0 });\r\n  }\r\n});\r\n","stylesSource":".qf-choice-editor,\n.qf-choice-practice {\n  --choice-accent: #7962ad;\n  --choice-soft: #f5f1fb;\n  --choice-line: #e8e3ed;\n  --choice-muted: #8a8295;\n  font: 15px/1.65 Arial, \"Microsoft YaHei\", sans-serif;\n  color: #302c3b;\n  min-width: 0;\n}\n\n.qf-choice-editor *,\n.qf-choice-practice * {\n  box-sizing: border-box\n}\n\n.qf-extension-page [hidden] {\n  display: none !important\n}\n\n.qf-choice-editor .muted,\n.qf-choice-practice .muted {\n  font-size: 12px;\n  color: var(--choice-muted);\n  margin: 0\n}\n\n.qf-type-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px\n}\n\n.qf-heading-copy {\n  display: grid;\n  gap: 3px;\n  flex: 1\n}\n\n.qf-eyebrow {\n  font-size: 11px;\n  color: var(--choice-muted);\n  letter-spacing: 1px\n}\n\n.qf-editor-heading strong {\n  font-size: 22px;\n  font-weight: 600;\n  line-height: 1.45\n}\n\n.qf-type-tag {\n  padding: 4px 11px;\n  border-radius: 6px;\n  color: var(--choice-accent);\n  background: #eee9f7;\n  font-size: 12px\n}\n\n.qf-type-meta {\n  display: flex;\n  justify-content: space-between;\n  gap: 12px;\n  font-size: 12px;\n  color: var(--choice-muted);\n  margin: 12px 0 24px\n}\n\n.qf-type-actions {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin: 24px 0 0\n}\n\n.qf-editor-actions {\n  margin: 18px 0 6px;\n  padding-bottom: 20px;\n  border-bottom: 1px solid var(--choice-line)\n}\n\n.qf-choice-editor button,\n.qf-choice-practice button,\n.qf-choice-editor select {\n  font: 13px/1.5 Arial, \"Microsoft YaHei\", sans-serif;\n  min-height: 36px;\n  padding: 7px 13px;\n  border: 1px solid #ded7e9;\n  border-radius: 8px;\n  background: white;\n  color: var(--choice-accent);\n  cursor: pointer;\n  transition: background .15s, border-color .15s;\n}\n\n.qf-choice-editor button:hover,\n.qf-choice-practice button:hover {\n  background: var(--choice-soft);\n  border-color: #c9bcde\n}\n\n.qf-choice-editor button.primary,\n.qf-choice-practice button.primary {\n  background: var(--choice-accent);\n  color: white;\n  border-color: var(--choice-accent);\n  padding-left: 20px;\n  padding-right: 20px\n}\n\n.qf-choice-editor button.primary:hover,\n.qf-choice-practice button.primary:hover {\n  background: #6a539d\n}\n\n.qf-choice-editor button:disabled,\n.qf-choice-practice button:disabled {\n  opacity: .45;\n  cursor: default\n}\n\n.qf-choice-editor button.danger,\n.qf-choice-editor button.quiet-danger {\n  color: #bd5264\n}\n\n.qf-choice-editor button:focus-visible,\n.qf-choice-practice button:focus-visible,\n.qf-choice-editor select:focus-visible {\n  outline: 2px solid #ad97d5;\n  outline-offset: 3px\n}\n\n.qf-editor-section {\n  margin-top: 24px\n}\n\n.qf-field {\n  display: grid;\n  gap: 10px\n}\n\n.qf-field-title,\n.qf-section-heading strong,\n.qf-type-sources>strong {\n  font-size: 14px;\n  font-weight: 600\n}\n\n.qf-section-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  margin-bottom: 10px\n}\n\n.qf-choice-editor textarea,\n.qf-choice-editor input[type=number],\n.qf-source-input input {\n  width: 100%;\n  font: inherit;\n  line-height: 1.65;\n  padding: 11px 13px;\n  border: 1px solid #dfd9e8;\n  border-radius: 8px;\n  background: #fff;\n  color: inherit;\n  outline: none;\n}\n\n.qf-choice-editor textarea {\n  resize: vertical;\n  display: block\n}\n\n.qf-choice-editor textarea:focus,\n.qf-choice-editor input[type=number]:focus,\n.qf-source-input input:focus {\n  border-color: #a18ac6;\n  box-shadow: 0 0 0 3px #7962ad0d\n}\n\n.qf-edit-options {\n  display: grid;\n  gap: 10px;\n  margin-top: 14px\n}\n\n.qf-choice-edit-row {\n  display: grid;\n  grid-template-columns: 20px 28px minmax(0, 1fr) auto;\n  align-items: center;\n  gap: 10px;\n  padding: 9px 10px;\n  border: 1px solid var(--choice-line);\n  border-radius: 10px;\n  background: #fcfbfd\n}\n\n.qf-choice-edit-row.is-correct {\n  background: var(--choice-soft);\n  border-color: #d8cbe9\n}\n\n.qf-option-letter {\n  font-weight: 600;\n  color: #756b86;\n  font-size: 14px;\n  flex: none\n}\n\n.qf-choice-edit-row.is-correct .qf-option-letter {\n  color: var(--choice-accent)\n}\n\n.qf-choice-edit-row textarea {\n  padding: 8px 10px;\n  min-height: 42px;\n  font-size: 14px\n}\n\n.qf-choice-edit-row button {\n  padding: 6px 8px;\n  min-height: 32px;\n  border-color: transparent;\n  background: transparent;\n  color: var(--choice-muted);\n  font-size: 12px\n}\n\n.qf-choice-edit-row button:hover {\n  color: #bd5264;\n  background: #fff1f3;\n  border-color: transparent\n}\n\n.qf-score-input {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  color: var(--choice-muted);\n  font-size: 13px\n}\n\n.qf-score-input input[type=number] {\n  width: 112px;\n  color: #302c3b\n}\n\n.qf-analysis-editor {\n  margin-top: 12px\n}\n\n.qf-choice-prompt {\n  margin: 0 0 14px;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  font-size: 18px;\n  font-weight: 500;\n  line-height: 1.8\n}\n\n.qf-choice-hint {\n  margin-bottom: 14px !important\n}\n\n.qf-choice-options {\n  display: grid;\n  gap: 10px\n}\n\n.qf-choice-option {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  padding: 14px 15px;\n  border: 1px solid #eeeaf2;\n  border-radius: 10px;\n  background: #fcfbfd;\n  cursor: pointer;\n  transition: background .15s, border-color .15s\n}\n\n.qf-choice-option:hover {\n  background: #f8f5fc;\n  border-color: #d8cde7\n}\n\n.qf-choice-option.selected {\n  background: var(--choice-soft);\n  border-color: #d4c5e7\n}\n\n.qf-choice-option .qf-option-text {\n  flex: 1;\n  min-width: 0;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere\n}\n\n.qf-choice-option input,\n.qf-choice-edit-row>input {\n  appearance: none;\n  -webkit-appearance: none;\n  width: 20px;\n  height: 20px;\n  flex: none;\n  position: relative;\n  border: 1.5px solid #cec7d6;\n  border-radius: 50%;\n  margin: 2px 0 0;\n  background: white;\n  cursor: pointer;\n}\n\n.qf-choice-option input[type=checkbox],\n.qf-choice-edit-row>input[type=checkbox] {\n  border-radius: 5px\n}\n\n.qf-choice-option input:checked,\n.qf-choice-edit-row>input:checked {\n  border-color: var(--choice-accent)\n}\n\n.qf-choice-option input:checked:after,\n.qf-choice-edit-row>input:checked:after {\n  content: \"\";\n  position: absolute;\n  inset: 4px;\n  background: var(--choice-accent);\n  border-radius: 50%\n}\n\n.qf-choice-option input[type=checkbox]:checked:after,\n.qf-choice-edit-row>input[type=checkbox]:checked:after {\n  content: \"✓\";\n  inset: -4px 0 0;\n  color: var(--choice-accent);\n  background: transparent;\n  font-size: 19px;\n  text-align: center\n}\n\n.qf-choice-option input:focus-visible,\n.qf-choice-edit-row>input:focus-visible {\n  outline: 2px solid #ad97d5;\n  outline-offset: 3px\n}\n\n.qf-choice-option input:disabled {\n  opacity: 1;\n  cursor: default\n}\n\n.qf-choice-option.correct {\n  background: #edf7f3;\n  border-color: #cce8dd;\n  color: #13876d\n}\n\n.qf-choice-option.incorrect {\n  background: #fff0f2;\n  border-color: #f2d3db;\n  color: #c64b63\n}\n\n.qf-choice-option.correct .qf-option-letter {\n  color: #13876d\n}\n\n.qf-choice-option.incorrect .qf-option-letter {\n  color: #c64b63\n}\n\n.qf-option-feedback {\n  font-size: 11px;\n  line-height: 24px;\n  flex: none;\n  white-space: nowrap\n}\n\n.qf-inline-confirm {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  flex-wrap: wrap;\n  padding: 14px 16px;\n  margin-top: 16px;\n  background: var(--choice-soft);\n  border: 1px solid #e0d6ed;\n  border-radius: 10px;\n  font-size: 13px\n}\n\n.qf-inline-confirm>span {\n  flex: 1;\n  min-width: 180px\n}\n\n.qf-result-panel {\n  margin-top: 26px;\n  padding: 20px;\n  border: 1px solid var(--choice-line);\n  border-radius: 12px;\n  background: #fcfbfd\n}\n\n.qf-result-heading {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  flex-wrap: wrap\n}\n\n.qf-result-heading p {\n  margin: 0\n}\n\n.qf-result-heading [data-verdict] {\n  font-size: 15px;\n  font-weight: 600\n}\n\n.qf-result-heading .correct {\n  color: #13876d\n}\n\n.qf-result-heading .incorrect {\n  color: #c64b63\n}\n\n.qf-result-score {\n  font-size: 13px;\n  color: var(--choice-accent);\n  padding: 4px 10px;\n  background: #eee9f7;\n  border-radius: 6px\n}\n\n.qf-correct-answer {\n  margin: 12px 0 0;\n  font-size: 13px;\n  color: #6a6178\n}\n\n.qf-result-analysis {\n  border-top: 1px solid var(--choice-line);\n  padding-top: 16px;\n  margin-top: 16px\n}\n\n.qf-result-analysis>strong {\n  font-size: 13px;\n  font-weight: 600\n}\n\n.qf-result-analysis [data-analysis] {\n  margin-top: 8px;\n  overflow-wrap: anywhere\n}\n\n.qf-type-sources {\n  border-top: 1px solid var(--choice-line);\n  padding-top: 18px;\n  margin-top: 26px;\n  font-size: 13px\n}\n\n.qf-type-source {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 10px\n}\n\n.qf-type-source>button:first-child {\n  max-width: 100%;\n  overflow-wrap: anywhere;\n  text-align: left\n}\n\n.qf-type-source>.muted {\n  flex: 1\n}\n\n.qf-source-input {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-top: 12px\n}\n\n.qf-source-input input {\n  flex: 1;\n  min-width: 0;\n  font-size: 13px\n}\n\n.qf-source-input button {\n  flex: none\n}\n\n.qf-choice-practice [data-stage-note] {\n  margin-top: 24px;\n  font-size: 11px;\n  line-height: 1.7\n}\n\n@media(max-width:520px) {\n  .qf-editor-heading {\n    flex-wrap: wrap\n  }\n\n  .qf-heading-copy {\n    min-width: 130px\n  }\n\n  .qf-editor-heading strong {\n    font-size: 20px\n  }\n\n  .qf-choice-edit-row {\n    grid-template-columns: 20px 22px minmax(0, 1fr) auto;\n    gap: 6px;\n    padding: 8px\n  }\n\n  .qf-choice-edit-row button {\n    padding: 6px 3px\n  }\n\n  .qf-choice-option {\n    padding: 12px 10px;\n    gap: 8px\n  }\n\n  .qf-option-feedback {\n    font-size: 10px\n  }\n\n  .qf-result-panel {\n    padding: 16px\n  }\n\n  .qf-choice-prompt {\n    font-size: 17px\n  }\n}"}]},{"manifest":{"packageFormatVersion":2,"sdkApiMajor":2,"id":"quizforge.types.true-false","name":"判断题","version":"2.1.2","types":[{"id":"TRUE_FALSE","label":"判断题","dataVersion":1,"family":"OBJECTIVE","capabilities":["editor","practice","preview","history"],"questionSchema":"question.schema.json","answerSchema":"answer.schema.json","rules":"type.js","editor":"editor.html","renderer":"practice.html","defaultQuestion":"default.json","editorScript":"editor.js","rendererScript":"practice.js","styles":["style.css"],"permissions":["question.edit","bank.save","bank.add","bank.duplicate","bank.delete","answer.write","practice.submit","practice.retry","navigation","sources.open","sources.manage","learning.mode","whiteboard.tools","whiteboard.history","whiteboard.clear","whiteboard.appearance","whiteboard.zoom"]}],"minSdkApiMinor":1},"assets":[{"typeId":"TRUE_FALSE","defaultQuestion":{"id":"q_template","type":"TRUE_FALSE","stimulusRefs":[],"prompt":{"kind":"TEXT","text":"一个题型扩展可以通过同一份练习页面，提供作答和只读历史回放。"},"payload":{"kind":"CHOICE","options":[{"id":"opt_template_true","content":{"kind":"TEXT","text":"正确"}},{"id":"opt_template_false","content":{"kind":"TEXT","text":"错误"}}]},"answerSpec":{"kind":"CHOICE","correctOptionIds":["opt_template_true"]},"scoreSpec":{"defaultMaxScore":1},"evaluationSpec":null,"analysis":{"kind":"TEXT","text":"正确。练习与历史共用题型页面，历史的只读状态由宿主统一控制；扩展根据接口返回的能力调整交互。"},"sourceRefs":[]},"questionSchemaSource":"{\r\n  \"type\": \"object\",\r\n  \"required\": [\r\n    \"id\",\r\n    \"type\",\r\n    \"prompt\",\r\n    \"payload\",\r\n    \"answerSpec\",\r\n    \"scoreSpec\"\r\n  ],\r\n  \"properties\": {\r\n    \"type\": {\r\n      \"const\": \"TRUE_FALSE\"\r\n    },\r\n    \"payload\": {\r\n      \"type\": \"object\",\r\n      \"required\": [\r\n        \"kind\",\r\n        \"options\"\r\n      ],\r\n      \"properties\": {\r\n        \"kind\": {\r\n          \"const\": \"CHOICE\"\r\n        },\r\n        \"options\": {\r\n          \"type\": \"array\",\r\n          \"minItems\": 2,\r\n          \"maxItems\": 2\r\n        }\r\n      }\r\n    },\r\n    \"answerSpec\": {\r\n      \"type\": \"object\",\r\n      \"required\": [\r\n        \"kind\",\r\n        \"correctOptionIds\"\r\n      ],\r\n      \"properties\": {\r\n        \"kind\": {\r\n          \"const\": \"CHOICE\"\r\n        },\r\n        \"correctOptionIds\": {\r\n          \"type\": \"array\",\r\n          \"minItems\": 1,\r\n          \"maxItems\": 1,\r\n          \"items\": {\r\n            \"type\": \"string\",\r\n            \"minLength\": 1\r\n          }\r\n        }\r\n      }\r\n    }\r\n  }\r\n}\r\n","answerSchemaSource":"{\r\n  \"type\": \"object\",\r\n  \"additionalProperties\": false,\r\n  \"properties\": {\r\n    \"selectedOptionIds\": {\r\n      \"type\": \"array\",\r\n      \"items\": {\r\n        \"type\": \"string\"\r\n      },\r\n      \"uniqueItems\": true,\r\n      \"maxItems\": 1\r\n    }\r\n  },\r\n  \"required\": [\r\n    \"selectedOptionIds\"\r\n  ]\r\n}\r\n","editorHtml":"<!-- 编辑页片段：宿主按 manifest 加载 editor.js 和 style.css；data-* 是脚本查询的绑定点。 -->\r\n<section class=\"qf-judgment-editor\">\r\n  <!-- 自定义题库管理 UI，对应 QF.bank；独立开发预览没有正式题库操作时由 JS 隐藏。 -->\r\n  <header class=\"qf-type-heading qf-editor-heading\">\r\n    <div class=\"qf-heading-copy\"><span class=\"qf-eyebrow\">题目编辑</span><strong data-type-title>判断题编辑</strong></div>\r\n    <span data-bank-position class=\"muted\"></span><button type=\"button\" data-bank-save class=\"primary\" hidden>保存题库</button>\r\n  </header>\r\n  <nav data-bank-actions class=\"qf-type-actions qf-editor-actions\" aria-label=\"题目操作\" hidden>\r\n    <select data-bank-add aria-label=\"新增题目类型\"></select>\r\n    <button type=\"button\" data-bank-duplicate>复制题目</button><button type=\"button\" data-bank-delete class=\"quiet-danger\">删除题目</button>\r\n  </nav>\r\n  <!-- 这里只绘制删除确认，真正删除当前整张题卡由宿主接口执行。 -->\r\n  <section data-delete-confirm class=\"qf-inline-confirm\" hidden>\r\n    <span>删除当前整张题卡？</span><button type=\"button\" data-delete-cancel>取消</button><button type=\"button\" data-delete-accept class=\"danger\">确认删除</button>\r\n  </section>\r\n  <!-- 题干为普通文本；editor.js 使用 textarea.value 与 QF.editor.update 绑定。 -->\r\n  <section class=\"qf-editor-section\">\r\n    <label class=\"qf-field\"><span class=\"qf-field-title\">题干</span><textarea data-prompt rows=\"4\" placeholder=\"输入题目内容…\"></textarea></label>\r\n  </section>\r\n  <section class=\"qf-editor-section\">\r\n    <div class=\"qf-section-heading\"><strong>正确答案</strong><span class=\"muted\">单选</span></div>\r\n    <p class=\"muted\">选择这句话的判断结果，练习时由用户作答。</p>\r\n    <!-- 编辑标准答案：固定两项，具体选项 ID 从数据读取，不在 HTML 中写死。 -->\r\n    <div class=\"qf-judgment-options\" role=\"radiogroup\" aria-label=\"正确答案\">\r\n      <label class=\"qf-choice-option\"><input type=\"radio\" name=\"correct-answer\" data-correct-true><span class=\"qf-judgment-symbol\" aria-hidden=\"true\">✓</span><span class=\"qf-option-text\">正确</span></label>\r\n      <label class=\"qf-choice-option\"><input type=\"radio\" name=\"correct-answer\" data-correct-false><span class=\"qf-judgment-symbol\" aria-hidden=\"true\">×</span><span class=\"qf-option-text\">错误</span></label>\r\n    </div>\r\n  </section>\r\n  <section class=\"qf-editor-section qf-score-section\">\r\n    <label class=\"qf-field\"><span class=\"qf-field-title\">分值</span><span class=\"qf-score-input\"><input data-score type=\"number\" min=\"0.01\" step=\"0.5\"><span>分</span></span></label>\r\n  </section>\r\n  <section class=\"qf-editor-section\">\r\n    <div class=\"qf-section-heading\"><strong>答案与解析</strong><span class=\"muted\">支持富文本</span></div>\r\n    <!-- 公共富文本编辑器挂载点；内容变化仍需要 editor.update 才能进入保存流程。 -->\r\n    <div data-analysis class=\"qf-analysis-editor\"></div>\r\n  </section>\r\n  <!-- 引用来源由宿主解析和打开，页面仅绑定 sources 接口。 -->\r\n  <section data-source-section class=\"qf-type-sources\" hidden>\r\n    <strong>引用来源</strong><div data-sources></div>\r\n    <div class=\"qf-source-input\"><input data-source-link placeholder=\"粘贴来源链接…\" aria-label=\"来源链接\"><button type=\"button\" data-source-add>添加来源</button></div>\r\n  </section>\r\n  <p data-qf-error class=\"practice-error\" role=\"alert\" hidden></p>\r\n</section>\r\n","rendererHtml":"<!-- 同一页面用于练习、草稿、历史与只读预览；差异由 practice.js 读取宿主能力决定。 -->\r\n<section class=\"qf-judgment-practice\">\r\n  <div class=\"qf-type-heading\"><span data-type-label class=\"qf-type-tag\"></span><span data-question-position\r\n      class=\"muted\"></span></div>\r\n  <div class=\"qf-type-meta\"><span data-max-score></span><span data-answer-state></span></div>\r\n  <!-- 题干是数据，通过 textContent 填入；HTML 中只写固定 UI，不写真实题目或标准答案。 -->\r\n  <div data-prompt class=\"qf-choice-prompt\"></div>\r\n  <p data-choice-hint class=\"qf-choice-hint muted\"></p>\r\n  <!-- radio 保留原生键盘操作。用户选择通过 QF.answer.update 保存当前选项 ID。 -->\r\n  <div class=\"qf-judgment-options\" role=\"radiogroup\" aria-label=\"判断结果\">\r\n    <label class=\"qf-choice-option\"><input type=\"radio\" name=\"judgment-answer\" data-answer-true><span class=\"qf-judgment-symbol\" aria-hidden=\"true\">✓</span><span class=\"qf-option-text\">正确</span><span class=\"qf-option-feedback\" hidden></span></label>\r\n    <label class=\"qf-choice-option\"><input type=\"radio\" name=\"judgment-answer\" data-answer-false><span class=\"qf-judgment-symbol\" aria-hidden=\"true\">×</span><span class=\"qf-option-text\">错误</span><span class=\"qf-option-feedback\" hidden></span></label>\r\n  </div>\r\n  <!-- 自己绘制提交/重试，因此 JS 隐藏了同名公共 UI；接口仍交给应用执行事务。 -->\r\n  <div class=\"qf-type-actions\" data-answer-actions>\r\n    <button type=\"button\" data-submit-answer class=\"primary\" hidden>提交答案</button><button type=\"button\" data-retry-answer\r\n      hidden>↻ 重新作答</button>\r\n  </div>\r\n  <!-- 本例自行确认，不使用宿主默认确认面板。点击确认才调用 practice.submit。 -->\r\n  <section data-answer-confirm class=\"qf-inline-confirm\" hidden>\r\n    <span>确认提交这道题的答案吗？</span><button type=\"button\" data-cancel-answer>继续作答</button><button type=\"button\"\r\n      data-confirm-answer class=\"primary\">确认提交</button>\r\n  </section>\r\n  <!-- 提交后或历史中才显示：从 getResult 读取得分、reference 和解析，不在页面判分。 -->\r\n  <section data-result class=\"qf-result-panel\" hidden>\r\n    <div class=\"qf-result-heading\">\r\n      <p data-verdict></p>\r\n      <p data-score class=\"qf-result-score\"></p>\r\n    </div>\r\n    <p data-correct-answer class=\"qf-correct-answer\"></p>\r\n    <div class=\"qf-result-analysis\"><strong>答案与解析</strong>\r\n      <div data-analysis></div>\r\n    </div>\r\n  </section>\r\n  <section data-source-section class=\"qf-type-sources\" hidden><strong>引用来源</strong>\r\n    <div data-sources></div>\r\n  </section>\r\n  <!-- 模式提示和错误反馈；草稿开关、画笔、缩放与尝试导航由宿主在页面外提供。 -->\r\n  <p data-stage-note class=\"muted\"></p>\r\n  <p data-qf-error class=\"practice-error\" role=\"alert\" hidden></p>\r\n</section>\r\n","editorSource":"// 判断题编辑页：宿主已注入 QF；HTML 负责结构，此文件负责数据与事件绑定。\r\n// 建议与 editor.html、default.json 对照阅读。更换题型时先改数据契约，再替换字段绑定。\r\n// QF.dom.on 注册的监听器会在页面销毁时清理，不需要自己实现 WebView 生命周期。\r\nconst $ = QF.dom.$, on = QF.dom.on;\r\n// 编辑页可以读取完整题目，包括标准答案；练习页提交前不能读取这些保密字段。\r\nconst reply = await QF.editor.getData();\r\nif (!reply.ok) throw new Error(reply.error.message);\r\nlet question = reply.data;\r\n// 初始布局：编辑页顶部自然排列；已有草稿几何由宿主恢复，不被初始配置覆盖。\r\nQF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'top', padding: 20 });\r\n// 本模板自己绘制保存、增删与来源 UI，因此隐藏对应默认控件。上一题/下一题仍由宿主保留。\r\n// 简单新题型可保留默认 UI，并删除下面不需要的操作区和绑定，不必复制全部管理代码。\r\nQF.ui.configure({ title: false, save: false, position: false, typeLabel: false, add: false, duplicate: false, delete: false, sources: false });\r\n$('[data-type-title]').textContent = '判断题编辑';\r\nlet actionBusy = false, shellRevision = 0;\r\nlet capabilities = {};\r\n// 正式题库编辑会话提供 QF.bank。独立开发预览没有该能力，此时隐藏正式题库操作。\r\n// response.ok 只表示接口可用；具体操作仍会经过声明权限、用户授权和宿主校验。\r\nasync function shellState() {\r\n  const revision = ++shellRevision;\r\n  const [response, context] = await Promise.all([QF.bank.getState(), QF.host.getContext()]);\r\n  if (revision !== shellRevision) return;\r\n  capabilities = context.ok ? context.data.capabilities : {};\r\n  refreshFields();\r\n  const available = response.ok;\r\n  $('[data-bank-save]').hidden = !available; $('[data-bank-actions]').hidden = !available; $('[data-source-section]').hidden = !available;\r\n  if (!available) return;\r\n  const state = response.data;\r\n  $('[data-bank-position]').textContent = `第 ${state.index + 1} / ${state.count} 题`;\r\n  const select = $('[data-bank-add]'); select.replaceChildren(new Option('＋ 新增题目', ''));\r\n  state.types.forEach(type => select.append(new Option(type.label, type.id)));\r\n  const rows = $('[data-sources]'); rows.replaceChildren();\r\n  state.sources.forEach((source, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-type-source';\r\n    // 来源文本使用 textContent；不把题库中的文字拼接成 HTML。\r\n    const open = document.createElement('button'); open.type = 'button'; open.textContent = source.label; open.disabled = actionBusy || !capabilities.viewSources || !source.navigable; open.title = source.message; open.dataset.sourceAction = 'open'; open.dataset.sourceIndex = index;\r\n    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message;\r\n    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = '移除'; remove.setAttribute('aria-label', '移除来源 ' + source.label); remove.dataset.sourceAction = 'remove'; remove.dataset.sourceIndex = index; remove.disabled = actionBusy || !capabilities.manageSources;\r\n    row.append(open, message, remove); rows.append(row);\r\n  });\r\n  const granted = context.ok ? context.data.permissions.granted : [];\r\n  for (const [selector, permission] of [['[data-bank-save]', 'bank.save'], ['[data-bank-add]', 'bank.add'], ['[data-bank-duplicate]', 'bank.duplicate'], ['[data-bank-delete]', 'bank.delete'], ['[data-delete-accept]', 'bank.delete'], ['[data-source-add]', 'sources.manage']])\r\n    $(selector).disabled = actionBusy || !state.editable || !granted.includes(permission);\r\n  $('[data-source-link]').disabled = actionBusy || !capabilities.manageSources;\r\n}\r\n// 防止重复操作；失败提示错误，finally 恢复控件并从应用读取最新状态。\r\nasync function runAction(action) {\r\n  if (actionBusy) return; actionBusy = true;\r\n  try { await shellState(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }\r\n  finally { actionBusy = false; await shellState(); }\r\n}\r\n// bank.save 等待当前编辑写入并保存整个 .qbank；editor.save 只是同步编辑草稿。\r\non($('[data-bank-save]'), 'click', () => runAction(() => QF.bank.save()));\r\n// 刷新会重建新增下拉框，所以在进入 runAction 前记录选择的题型。\r\non($('[data-bank-add]'), 'change', () => { const type = $('[data-bank-add]').value; if (type) return runAction(() => QF.bank.addQuestion(type)); });\r\non($('[data-bank-duplicate]'), 'click', () => runAction(() => QF.bank.duplicateQuestion()));\r\non($('[data-bank-delete]'), 'click', () => { $('[data-delete-confirm]').hidden = false; });\r\non($('[data-delete-cancel]'), 'click', () => { $('[data-delete-confirm]').hidden = true; });\r\n// 删除由宿主执行，针对当前整张题卡；页面只负责确认，不直接删除文件或数据库记录。\r\non($('[data-delete-accept]'), 'click', () => runAction(() => QF.bank.deleteQuestion()));\r\n// 来源链接交给宿主解析，页面不自行请求网络或改写 sourceRefs 身份。\r\nasync function addSource() {\r\n  const link = $('[data-source-link]').value;\r\n  const response = await runAction(() => QF.sources.add(link));\r\n  if (response?.ok) $('[data-source-link]').value = '';\r\n}\r\non($('[data-source-add]'), 'click', addSource);\r\non($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-action]'); if (button && !button.disabled) return runAction(() => button.dataset.sourceAction === 'open' ? QF.sources.open(Number(button.dataset.sourceIndex)) : QF.sources.remove(Number(button.dataset.sourceIndex))); });\r\non($('[data-source-link]'), 'keydown', event => { if (event.key === 'Enter') { event.preventDefault(); return addSource(); } });\r\n// 权限或会话状态变化后刷新操作区；订阅用于 UI 更新，不等于保存。\r\n\r\n// update 是完整 Question 的顶层合并；子对象要保留需要的全部字段。\r\n// 错误时 question 保留上次接受的值。不能借此更改当前题目的 id/type。\r\n// Apply a local patch immediately so the next keystroke never builds on an old reply.\r\nlet editRevision = 0;\r\nasync function update(patch) {\r\n  const revision = ++editRevision;\r\n  question = { ...question, ...patch };\r\n  const response = await QF.editor.update(patch);\r\n  if (response.ok) {\r\n    if (revision === editRevision) question = response.data;\r\n  } else {\r\n    QF.ui.notify(response.error.message);\r\n    const saved = await QF.editor.getData();\r\n    if (revision === editRevision && saved.ok) question = saved.data;\r\n  }\r\n  return response;\r\n}\r\nfunction refreshFields() {\r\n  const disabled = actionBusy || !capabilities.editQuestion;\r\n  for (const input of QF.dom.root.querySelectorAll('textarea, input, [data-add-option]')) {\r\n    if (!input.matches('[data-source-link]')) input.disabled = disabled;\r\n  }\r\n  for (const button of QF.dom.root.querySelectorAll('[data-option-remove]'))\r\n    button.disabled = disabled || question.payload.options.length <= 2;\r\n}\r\nfunction updateScore() {\r\n  const value = $('[data-score]').value;\r\n  const score = Number(value);\r\n  if (!value.trim() || !Number.isFinite(score) || score <= 0) {\r\n    QF.ui.notify('分值必须是大于 0 的数字'); return;\r\n  }\r\n  return update({ scoreSpec: { ...question.scoreSpec, defaultMaxScore: score } });\r\n}\r\n$('[data-prompt]').value = question.prompt.text;\r\non($('[data-prompt]'), 'input', () => update({ prompt: { kind: 'TEXT', text: $('[data-prompt]').value } }));\r\n$('[data-score]').value = question.scoreSpec.defaultMaxScore;\r\non($('[data-score]'), 'input', updateScore);\r\n// 两个选项固定为“正确／错误”；身份从当前题目读取，新建和复制会重新分配选项 ID。\r\n// 不要写死 default.json 的 opt_template_*，否则复制后的标准答案将引用错误身份。\r\nconst answers = [$('[data-correct-true]'), $('[data-correct-false]')];\r\nfunction refreshAnswer() {\r\n  answers.forEach((input, index) => {\r\n    input.checked = question.answerSpec.correctOptionIds.includes(question.payload.options[index].id);\r\n    input.closest('label').classList.toggle('selected', input.checked);\r\n  });\r\n}\r\nanswers.forEach((input, index) => on(input, 'change', async () => {\r\n  // answerSpec 是标准答案；用户在练习中的选择另存于 QF.answer。\r\n  await update({ answerSpec: { kind: 'CHOICE', correctOptionIds: [question.payload.options[index].id] } });\r\n  refreshAnswer();\r\n}));\r\nrefreshAnswer();\r\n// 公共内容编辑器支持富文本；onChange 明确将内容交给 editor.update，挂载本身不会保存。\r\nQF.content.mountEditor($('[data-analysis]'), { value: question.analysis, formatting: true, onChange: analysis => update({ analysis }) });\r\n\r\nQF.host.subscribe(shellState); await shellState();\r\n","rendererSource":"// 练习、草稿、历史和网页预览共用此页：宿主给出数据、状态与能力，页面按能力绘制。\r\n// 草稿白板、正式尝试保存和只读限制由宿主管理，不要再写第二套记录或白板存储。\r\nconst $ = QF.dom.$, on = QF.dom.on;\r\n// 提交前 getQuestion 不含 answerSpec/analysis；标准答案只能在允许显示结果后读取。\r\nconst reply = await QF.practice.getQuestion(); if (!reply.ok) throw new Error(reply.error.message);\r\nconst question = reply.data;\r\n// 声明题卡首次显示的宽度、对齐和留白；恢复过的草稿位置与尺寸优先。\r\nQF.layout.configure({ cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'center', padding: 20 });\r\n// 自己绘制提交、确认、重试与反馈，隐藏对应默认 UI；仍保留默认草稿入口和悬浮工具。\r\n// 隐藏按钮不会增加权限；confirmation:false 只省略宿主确认，不省略提交事务。\r\nQF.ui.configure({ typeLabel: false, position: false, score: false, state: false, submit: false, retry: false, confirmation: false, note: false, sources: false, draftToggle: true, draftToolbar: true, draftZoom: true });\r\nlet confirming = false, actionBusy = false, refreshRevision = 0, answerRevision = 0, answerWrites = 0;\r\n$('[data-type-label]').textContent = '判断题';\r\n$('[data-choice-hint]').textContent = '请选择这句话的判断结果';\r\n// 暂时禁用操作，避免连点；结果来自应用，不能通过页面自己修改 score/state。\r\nasync function runAction(action) {\r\n  if (actionBusy) return; actionBusy = true;\r\n  try { await refresh(); const response = await action(); if (!response.ok) QF.ui.notify(response.error.message); return response; }\r\n  finally { actionBusy = false; await refresh(); }\r\n}\r\n// 页面中的确认面板只处理 UX；真正的校验、评分和尝试记录保存由 practice.submit 执行。\r\non($('[data-submit-answer]'), 'click', () => { confirming = true; $('[data-answer-confirm]').hidden = false; refresh().then(() => $('[data-confirm-answer]').focus()); });\r\non($('[data-cancel-answer]'), 'click', () => { confirming = false; refresh(); });\r\non($('[data-confirm-answer]'), 'click', () => { confirming = false; return runAction(() => QF.practice.submit()); });\r\n// retry 保留旧尝试，开始空白作答/草稿；下一次 submit 成功才创建新的尝试记录。\r\non($('[data-retry-answer]'), 'click', () => runAction(() => QF.practice.retry()));\r\non($('[data-sources]'), 'click', event => { const button = event.target.closest('[data-source-index]'); if (button && !button.disabled) return runAction(() => QF.sources.open(Number(button.dataset.sourceIndex))); });\r\n$('[data-prompt]').textContent = question.prompt.text;\r\n// UI 显示固定选项，但选择保存当前题目中的选项 ID，不保存“正确/错误”字符串或 DOM。\r\nconst controls = [$('[data-answer-true]'), $('[data-answer-false]')].map((input, index) => {\r\n  const option = question.payload.options[index], row = input.closest('label');\r\n  input.value = option.id; input.setAttribute('aria-label', option.content.text);\r\n  on(input, 'change', async () => {\r\n    // Invalidate reads already in flight; never repaint an older answer over a newer click.\r\n    ++answerRevision; ++refreshRevision; ++answerWrites;\r\n    const selectedOptionIds = [option.id];\r\n    row.classList.toggle('selected', input.checked);\r\n    try {\r\n      const response = await QF.answer.update({ selectedOptionIds });\r\n      if (!response.ok) QF.ui.notify(response.error.message);\r\n    } finally {\r\n      --answerWrites;\r\n      if (!answerWrites) await refresh();\r\n    }\r\n  });\r\n  return { option, input, row, feedback: row.querySelector('.qf-option-feedback') };\r\n});\r\n// 从宿主重新读取权威状态。历史返回所选尝试的答案、结果；权限变化也会触发订阅。\r\n// 文本输入题复用此流程时，需要处理输入法和未完成写入，避免异步旧状态覆盖新输入。\r\nasync function refresh() {\r\n  const revision = ++refreshRevision, answerVersion = answerRevision;\r\n  const [a, c, r, s, n] = await Promise.all([QF.answer.get(), QF.host.getContext(), QF.practice.getResult(), QF.practice.getState(), QF.navigation.getState()]);\r\n  if (revision !== refreshRevision || answerVersion !== answerRevision) return;\r\n  if (!a.ok || !c.ok || !r.ok || !s.ok) return;\r\n  const selected = new Set(a.data.selectedOptionIds || []), result = r.data;\r\n  const capabilities = c.data.capabilities, state = s.data;\r\n  const readOnly = c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW';\r\n  const permissions = c.data.permissions.granted;\r\n  $('[data-question-position]').textContent = Number.isInteger(state.index) ? `第 ${state.index + 1} / ${state.total} 题` : '';\r\n  $('[data-max-score]').textContent = `分值：${state.maxScore ?? '未设置'}`;\r\n  $('[data-answer-state]').textContent = ({ UNANSWERED: '未作答', DRAFT: '已选择', SUBMITTED: '已提交', RETRYING: '重试中', REVISING: '修订中' })[state.state] || '';\r\n  if (!capabilities.submit || result || c.data.mode === 'HISTORY' || c.data.mode === 'PREVIEW') confirming = false;\r\n  $('[data-answer-confirm]').hidden = !confirming;\r\n  // 模式、权限和结果决定展示；临时禁用只影响操作，避免切题时按钮消失、题卡抖动。\r\n  // 即使控件漏禁用，宿主仍会拒绝只读写入。\r\n  $('[data-submit-answer]').hidden = readOnly || !permissions.includes('practice.submit') || Boolean(result);\r\n  $('[data-submit-answer]').disabled = actionBusy || confirming || !capabilities.submit || selected.size === 0;\r\n  $('[data-retry-answer]').hidden = readOnly || !permissions.includes('practice.retry') || !result;\r\n  $('[data-retry-answer]').disabled = actionBusy || !capabilities.retry;\r\n  $('[data-confirm-answer]').disabled = actionBusy || !capabilities.submit || selected.size === 0;\r\n  const sourceRows = $('[data-sources]'); sourceRows.replaceChildren();\r\n  const sources = n.ok ? n.data.sources : []; $('[data-source-section]').hidden = !sources.length;\r\n  sources.forEach((source, index) => {\r\n    const row = document.createElement('div'); row.className = 'qf-type-source'; const button = document.createElement('button'); button.type = 'button'; button.textContent = source.label; button.disabled = actionBusy || !capabilities.viewSources || !source.navigable; button.dataset.sourceIndex = index;\r\n    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message; row.append(button, message); sourceRows.append(row);\r\n  });\r\n  $('[data-stage-note]').textContent = c.data.mode === 'HISTORY' ? '历史草稿 · 只读' : c.data.mode === 'PREVIEW' ? '只读预览' : '草稿自动保存；提交后冻结，重试从空白草稿开始。';\r\n  // reference 是提交后公开的标准答案快照；未提交时 result 为 null，不展示正确性。\r\n  const correct = result?.reference?.answerSpec?.correctOptionIds || result?.correctOptionIds || [];\r\n  for (const { option, input, row, feedback } of controls) {\r\n    // 只读/提交后仍设置 checked，禁用只是禁止改答，不能丢掉用户已选标记。\r\n    if (!answerWrites) input.checked = selected.has(option.id);\r\n    input.disabled = actionBusy || confirming || !capabilities.editAnswer;\r\n    row.classList.toggle('selected', input.checked);\r\n    row.classList.toggle('correct', Boolean(result) && correct.includes(option.id));\r\n    row.classList.toggle('incorrect', Boolean(result) && input.checked && !correct.includes(option.id));\r\n    feedback.hidden = !result || (!input.checked && !correct.includes(option.id));\r\n    feedback.textContent = correct.includes(option.id) ? (input.checked ? '正确 · 已选' : '正确答案') : '你的答案';\r\n  }\r\n  $('[data-result]').hidden = !result;\r\n  if (result) {\r\n    // 得分和判定只使用 getResult 返回值；页面没有评分函数，也不直接写入历史。\r\n    $('[data-verdict]').textContent = result.status === 'CORRECT' ? '回答正确' : result.status === 'INCORRECT' ? '回答错误' : '未评分';\r\n    $('[data-verdict]').className = result.status === 'CORRECT' ? 'correct' : 'incorrect';\r\n    $('[data-score]').textContent = '得分：' + (result.score ?? '未评分') + ' / ' + result.maxScore;\r\n    $('[data-correct-answer]').textContent = '正确答案：' + question.payload.options.map(o => correct.includes(o.id) ? o.content.text : null).filter(Boolean).join('、');\r\n    // 解析使用公共内容渲染器，支持 TEXT/RICH 等宿主内容结构。\r\n    QF.content.render($('[data-analysis]'), result.reference?.analysis || result.analysis || { kind: 'TEXT', text: '' });\r\n  }\r\n}\r\n// 初始化一次，随后随提交、重试、尝试查看和权限变化刷新；不自己重建整张题卡模拟轮次。\r\nQF.host.subscribe(refresh); await refresh();\r\n","rulesSource":"// 独立、无 DOM 的规则文件。此处只有规则版 QF，不可使用页面的 editor/answer/dom 接口。\n// 宿主载入 default.json，提供模板创建、复制、快照与默认单题大纲；作者只写业务规则。\nQF.defineQuestionType({\n  // 与 manifest.types[].id、default.json.type、题目 Schema 中 type.const 保持一致。\n  type: 'TRUE_FALSE',\n  // Schema 先校验结构，这里补业务约束；不能通过返回 [] 取消宿主 Schema 检查。\n  validate(question) {\n    const errors = [];\n    if (question.prompt?.kind !== 'TEXT' || typeof question.prompt.text !== 'string' || !question.prompt.text.trim()) {\n      errors.push('请填写普通文本题干');\n    }\n    const options = question.payload?.options;\n    // 固定两项及顺序，同时保证 ID 独立；页面只改变哪个选项是标准答案。\n    const validOptions = question.payload?.kind === 'CHOICE' && Array.isArray(options) && options.length === 2\n      && options.every((option, index) => typeof option?.id === 'string' && option.id.startsWith('opt_')\n        && option.content?.kind === 'TEXT' && option.content.text === ['正确', '错误'][index])\n      && options[0].id !== options[1].id;\n    if (!validOptions) errors.push('判断题需按顺序保留正确、错误两个固定选项和独立选项标识');\n    const correct = question.answerSpec?.correctOptionIds;\n    // 标准答案必须引用当前题目的有效选项，不能引用其他题目或默认模板的旧身份。\n    if (question.answerSpec?.kind !== 'CHOICE' || !Array.isArray(correct) || correct.length !== 1\n      || !validOptions || !options.some(option => option.id === correct[0])) errors.push('请选择有效的正确答案');\n    if (!Number.isFinite(question.scoreSpec?.defaultMaxScore) || question.scoreSpec.defaultMaxScore <= 0) {\n      errors.push('分值必须为正数');\n    }\n    return errors;\n  },\n  // 用户作答和标准答案分开校验；空数组可暂存，但 empty:true 会阻止直接提交。\n  // 宿主保留的 {} 未作答状态由适配层处理，不会直接进入本函数。\n  validateAnswer(question, answer) {\n    const selected = answer.selectedOptionIds;\n    const valid = Array.isArray(selected) && selected.length <= 1\n      && selected.every(id => question.payload.options.some(option => option.id === id));\n    return { empty: valid && selected.length === 0, errors: valid ? [] : ['请选择正确或错误中的一个选项'] };\n  },\n  // 同步评分使用应用提供的冻结题目、作答和满分，不能从页面读取 radio 或调用网络/AI。\n  grade({ question, answer, maxScore, reportResult }) {\n    const selected = answer.selectedOptionIds || [];\n    const right = selected.length === 1 && selected[0] === question.answerSpec.correctOptionIds[0];\n    // 每次上报一次，宿主验证 0～满分并在事务成功后保存；不是页面直接写入历史。\n    // 规则适配层根据满分/非满分生成 CORRECT/INCORRECT，异步 Promise 评分尚未支持。\n    return reportResult({ score: right ? maxScore : 0 });\n  }\n});\n","stylesSource":"/* 判断题视觉模板：复制到新拓展后可定制。变量控制强调色、浅底、分隔与辅助文字。\r\n   CSS 负责题型页面内部；题卡几何通过 QF.layout 配置，白板与浏览区导航由宿主提供。 */\r\n.qf-judgment-editor, .qf-judgment-practice { --qf-accent: #7962ad; --qf-soft: #f5f1fb; --qf-line: #e8e3ed; --qf-muted: #8a8295; font: 15px/1.65 Arial, \"Microsoft YaHei\", sans-serif; color: #302c3b; min-width: 0; }\r\n.qf-judgment-editor *, .qf-judgment-practice * { box-sizing: border-box }\r\n/* JS 根据宿主能力切换 hidden；确保本文件其他 display 规则不会把隐藏控件重新显示。 */\r\n.qf-extension-page [hidden] { display: none !important }\r\n.qf-judgment-editor .muted, .qf-judgment-practice .muted { font-size: 12px; color: var(--qf-muted); margin: 0 }\r\n.qf-type-heading { display: flex; align-items: center; justify-content: space-between; gap: 14px }\r\n.qf-heading-copy { display: grid; gap: 3px; flex: 1 }\r\n.qf-eyebrow { font-size: 11px; color: var(--qf-muted); letter-spacing: 1px }\r\n.qf-editor-heading strong { font-size: 22px; font-weight: 600; line-height: 1.45 }\r\n.qf-type-tag { padding: 4px 11px; border-radius: 6px; color: var(--qf-accent); background: #eee9f7; font-size: 12px }\r\n.qf-type-meta { display: flex; justify-content: space-between; gap: 12px; font-size: 12px; color: var(--qf-muted); margin: 12px 0 24px }\r\n.qf-type-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 24px 0 0 }\r\n.qf-editor-actions { margin: 18px 0 6px; padding-bottom: 20px; border-bottom: 1px solid var(--qf-line) }\r\n.qf-judgment-editor button, .qf-judgment-practice button, .qf-judgment-editor select { font: 13px/1.5 Arial, \"Microsoft YaHei\", sans-serif; min-height: 36px; padding: 7px 13px; border: 1px solid #ded7e9; border-radius: 8px; background: white; color: var(--qf-accent); cursor: pointer; transition: background .15s, border-color .15s; }\r\n.qf-judgment-editor button:hover, .qf-judgment-practice button:hover { background: var(--qf-soft); border-color: #c9bcde }\r\n.qf-judgment-editor button.primary, .qf-judgment-practice button.primary { background: var(--qf-accent); color: white; border-color: var(--qf-accent); padding-left: 20px; padding-right: 20px }\r\n.qf-judgment-editor button.primary:hover, .qf-judgment-practice button.primary:hover { background: #6a539d }\r\n.qf-judgment-editor button:disabled, .qf-judgment-practice button:disabled { opacity: .45; cursor: default }\r\n.qf-judgment-editor button.danger, .qf-judgment-editor button.quiet-danger { color: #bd5264 }\r\n.qf-judgment-editor button:focus-visible, .qf-judgment-practice button:focus-visible, .qf-judgment-editor select:focus-visible { outline: 2px solid #ad97d5; outline-offset: 3px }\r\n.qf-editor-section { margin-top: 24px }\r\n.qf-field { display: grid; gap: 10px }\r\n.qf-field-title, .qf-section-heading strong, .qf-type-sources>strong { font-size: 14px; font-weight: 600 }\r\n.qf-section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 10px }\r\n.qf-judgment-editor textarea, .qf-judgment-editor input[type=number], .qf-source-input input { width: 100%; font: inherit; line-height: 1.65; padding: 11px 13px; border: 1px solid #dfd9e8; border-radius: 8px; background: #fff; color: inherit; outline: none; }\r\n.qf-judgment-editor textarea { resize: vertical; display: block }\r\n.qf-judgment-editor textarea:focus, .qf-judgment-editor input[type=number]:focus, .qf-source-input input:focus { border-color: #a18ac6; box-shadow: 0 0 0 3px #7962ad0d }\r\n.qf-score-input { display: flex; align-items: center; gap: 10px; color: var(--qf-muted); font-size: 13px }\r\n.qf-score-input input[type=number] { width: 112px; color: #302c3b }\r\n.qf-analysis-editor { margin-top: 12px }\r\n/* 普通文本保留换行，长词可换行；不要把题干改成依赖 innerHTML 的富文本实现。 */\r\n.qf-choice-prompt { margin: 0 0 14px; white-space: pre-wrap; overflow-wrap: anywhere; font-size: 18px; font-weight: 500; line-height: 1.8 }\r\n.qf-choice-hint { margin-bottom: 14px !important }\r\n.qf-choice-option { display: flex; align-items: flex-start; gap: 12px; padding: 14px 15px; border: 1px solid #eeeaf2; border-radius: 10px; background: #fcfbfd; cursor: pointer; transition: background .15s, border-color .15s }\r\n.qf-choice-option:hover { background: #f8f5fc; border-color: #d8cde7 }\r\n.qf-choice-option.selected { background: var(--qf-soft); border-color: #d4c5e7 }\r\n.qf-choice-option .qf-option-text { flex: 1; min-width: 0; white-space: pre-wrap; overflow-wrap: anywhere }\r\n/* 保留原生 input 的 checked/disabled/键盘行为，仅定制外观。 */\r\n.qf-choice-option input { appearance: none; -webkit-appearance: none; width: 20px; height: 20px; flex: none; position: relative; border: 1.5px solid #cec7d6; border-radius: 50%; margin: 2px 0 0; background: white; cursor: pointer; }\r\n.qf-choice-option input[type=checkbox] { border-radius: 5px }\r\n.qf-choice-option input:checked { border-color: var(--qf-accent) }\r\n.qf-choice-option input:checked:after { content: \"\"; position: absolute; inset: 4px; background: var(--qf-accent); border-radius: 50% }\r\n.qf-choice-option input[type=checkbox]:checked:after { content: \"✓\"; inset: -4px 0 0; color: var(--qf-accent); background: transparent; font-size: 19px; text-align: center }\r\n.qf-choice-option input:focus-visible { outline: 2px solid #ad97d5; outline-offset: 3px }\r\n/* 提交和历史只读后仍保留紫色已选圆点，禁用不代表清除答案。 */\r\n.qf-choice-option input:disabled { opacity: 1; cursor: default }\r\n/* 正确/错误来自接口返回的评分结果；文字反馈同时表达含义，避免只依赖颜色。 */\r\n.qf-choice-option.correct { background: #edf7f3; border-color: #cce8dd; color: #13876d }\r\n.qf-choice-option.incorrect { background: #fff0f2; border-color: #f2d3db; color: #c64b63 }\r\n.qf-option-feedback { font-size: 11px; line-height: 24px; flex: none; white-space: nowrap }\r\n.qf-inline-confirm { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 14px 16px; margin-top: 16px; background: var(--qf-soft); border: 1px solid #e0d6ed; border-radius: 10px; font-size: 13px }\r\n.qf-inline-confirm>span { flex: 1; min-width: 180px }\r\n.qf-result-panel { margin-top: 26px; padding: 20px; border: 1px solid var(--qf-line); border-radius: 12px; background: #fcfbfd }\r\n.qf-result-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap }\r\n.qf-result-heading p { margin: 0 }\r\n.qf-result-heading [data-verdict] { font-size: 15px; font-weight: 600 }\r\n.qf-result-heading .correct { color: #13876d }\r\n.qf-result-heading .incorrect { color: #c64b63 }\r\n.qf-result-score { font-size: 13px; color: var(--qf-accent); padding: 4px 10px; background: #eee9f7; border-radius: 6px }\r\n.qf-correct-answer { margin: 12px 0 0; font-size: 13px; color: #6a6178 }\r\n.qf-result-analysis { border-top: 1px solid var(--qf-line); padding-top: 16px; margin-top: 16px }\r\n.qf-result-analysis>strong { font-size: 13px; font-weight: 600 }\r\n.qf-result-analysis [data-analysis] { margin-top: 8px; overflow-wrap: anywhere }\r\n.qf-type-sources { border-top: 1px solid var(--qf-line); padding-top: 18px; margin-top: 26px; font-size: 13px }\r\n.qf-type-source { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-top: 10px }\r\n.qf-type-source>button:first-child { max-width: 100%; overflow-wrap: anywhere; text-align: left }\r\n.qf-type-source>.muted { flex: 1 }\r\n.qf-source-input { display: flex; align-items: center; gap: 10px; margin-top: 12px }\r\n.qf-source-input input { flex: 1; min-width: 0; font-size: 13px }\r\n.qf-source-input button { flex: none }\r\n.qf-judgment-practice [data-stage-note] { margin-top: 24px; font-size: 11px; line-height: 1.7 }\r\n@media(max-width:520px) {\r\n.qf-editor-heading { flex-wrap: wrap }\r\n.qf-heading-copy { min-width: 130px }\r\n.qf-editor-heading strong { font-size: 20px }\r\n.qf-choice-option { padding: 12px 10px; gap: 8px }\r\n.qf-option-feedback { font-size: 10px }\r\n.qf-result-panel { padding: 16px }\r\n.qf-choice-prompt { font-size: 17px }\r\n}\r\n/* 判断题的固定两项同宽并排；后续题型可以替换自己的作答区域。 */\r\n.qf-judgment-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 16px; }\r\n.qf-judgment-options .qf-choice-option { align-items: center; flex-wrap: wrap; min-height: 76px; padding: 18px; }\r\n.qf-judgment-options .qf-option-text { font-size: 16px; font-weight: 600; }\r\n.qf-judgment-options input { margin: 0; }\r\n.qf-judgment-symbol { font-size: 21px; font-weight: 500; line-height: 1; color: #8a8295; }\r\n.qf-choice-option.selected .qf-judgment-symbol { color: var(--qf-accent); }\r\n.qf-choice-option.correct .qf-judgment-symbol { color: #13876d; }\r\n.qf-choice-option.incorrect .qf-judgment-symbol { color: #c64b63; }\r\n.qf-choice-option:has(input:disabled) { cursor: default; }\r\n.qf-choice-option:has(input:disabled):not(.selected):not(.correct):not(.incorrect):hover { background: #fcfbfd; border-color: #eeeaf2; }\r\n.qf-judgment-options .qf-option-feedback { flex-basis: 100%; padding-left: 32px; }\r\n/* 极窄区域改成单列，不设置固定高度或页面内部滚动容器。 */\r\n@media (max-width: 380px) {\r\n.qf-judgment-options { grid-template-columns: 1fr; }\r\n}\r\n/* 尊重用户的减少动态效果偏好。 */\r\n@media (prefers-reduced-motion: reduce) {\r\n.qf-choice-option, .qf-judgment-editor button, .qf-judgment-practice button { transition: none; }\r\n}\r\n"}]}];
await Promise.all(packages.map(p=>window.questionExtensions.install(p)));
const selector=document.querySelector('#type'), questions=[];
for(const p of packages)for(const a of p.assets){questions.push(a);const o=document.createElement('option');o.value=a.typeId;o.textContent=p.manifest.types.find(t=>t.id===a.typeId).label;selector.append(o);}
function show(){const a=questions.find(a=>a.typeId===selector.value)||questions[0];if(a)window.questionPreview.showQuestion(a.defaultQuestion);}
selector.addEventListener('change',show);show();